"""ISC2 Certified Secure Software Lifecycle Professional (CSSLP): current eight-domain exam outline."""

CATEGORIES = [
    {'key': 'csslpConcepts', 'label': 'Secure Software Concepts', 'marks': 12, 'resources': [{'label': 'ISC2: CSSLP certification exam outline (Domain 1)', 'url': 'https://www.isc2.org/certifications/csslp/csslp-certification-exam-outline'}, {'label': 'CISA: Secure by Design', 'url': 'https://www.cisa.gov/securebydesign'}]},
    {'key': 'csslpLifecycle', 'label': 'Secure Software Lifecycle Management', 'marks': 11, 'resources': [{'label': 'ISC2: CSSLP certification exam outline (Domain 2)', 'url': 'https://www.isc2.org/certifications/csslp/csslp-certification-exam-outline'}, {'label': 'NIST: Secure Software Development Framework (SSDF), SP 800-218', 'url': 'https://csrc.nist.gov/projects/ssdf'}, {'label': 'OWASP: Software Assurance Maturity Model (SAMM)', 'url': 'https://owaspsamm.org/'}]},
    {'key': 'csslpReq', 'label': 'Secure Software Requirements', 'marks': 13, 'resources': [{'label': 'ISC2: CSSLP certification exam outline (Domain 3)', 'url': 'https://www.isc2.org/certifications/csslp/csslp-certification-exam-outline'}, {'label': 'OWASP: Application Security Verification Standard (ASVS)', 'url': 'https://owasp.org/www-project-application-security-verification-standard/'}]},
    {'key': 'csslpDesign', 'label': 'Secure Software Architecture and Design', 'marks': 15, 'resources': [{'label': 'ISC2: CSSLP certification exam outline (Domain 4)', 'url': 'https://www.isc2.org/certifications/csslp/csslp-certification-exam-outline'}, {'label': 'OWASP: Threat Modeling', 'url': 'https://owasp.org/www-community/Threat_Modeling'}, {'label': 'NIST: Zero Trust Architecture, SP 800-207', 'url': 'https://csrc.nist.gov/pubs/sp/800/207/final'}]},
    {'key': 'csslpImpl', 'label': 'Secure Software Implementation', 'marks': 14, 'resources': [{'label': 'ISC2: CSSLP certification exam outline (Domain 5)', 'url': 'https://www.isc2.org/certifications/csslp/csslp-certification-exam-outline'}, {'label': 'OWASP: Top 10', 'url': 'https://owasp.org/Top10/'}, {'label': 'OWASP: Cheat Sheet Series', 'url': 'https://cheatsheetseries.owasp.org/'}]},
    {'key': 'csslpTest', 'label': 'Secure Software Testing', 'marks': 14, 'resources': [{'label': 'ISC2: CSSLP certification exam outline (Domain 6)', 'url': 'https://www.isc2.org/certifications/csslp/csslp-certification-exam-outline'}, {'label': 'OWASP: Web Security Testing Guide', 'url': 'https://owasp.org/www-project-web-security-testing-guide/'}, {'label': 'NIST: Technical Guide to Information Security Testing and Assessment, SP 800-115', 'url': 'https://csrc.nist.gov/pubs/sp/800/115/final'}]},
    {'key': 'csslpDeploy', 'label': 'Secure Software Deployment, Operations and Maintenance', 'marks': 11, 'resources': [{'label': 'ISC2: CSSLP certification exam outline (Domain 7)', 'url': 'https://www.isc2.org/certifications/csslp/csslp-certification-exam-outline'}, {'label': 'NIST: Guide to Enterprise Patch Management Planning, SP 800-40 Rev. 4', 'url': 'https://csrc.nist.gov/pubs/sp/800/40/r4/final'}, {'label': 'NIST: Guidelines for Media Sanitization, SP 800-88 Rev. 1', 'url': 'https://csrc.nist.gov/pubs/sp/800/88/r1/final'}]},
    {'key': 'csslpSupply', 'label': 'Secure Software Supply Chain', 'marks': 10, 'resources': [{'label': 'ISC2: CSSLP certification exam outline (Domain 8)', 'url': 'https://www.isc2.org/certifications/csslp/csslp-certification-exam-outline'}, {'label': 'CISA: Software Bill of Materials (SBOM)', 'url': 'https://www.cisa.gov/sbom'}, {'label': 'SLSA: Supply-chain Levels for Software Artifacts', 'url': 'https://slsa.dev/'}]},
]

FLASHCARDS = [
    {'id': 'f1', 'cat': 'csslpConcepts', 'front': 'Confidentiality, integrity, availability (CIA triad)', 'back': 'Confidentiality keeps information from unauthorized disclosure, integrity keeps it accurate and unaltered by unauthorized change, and availability keeps it usable when authorized users need it. Nearly every security requirement, threat and control can be traced back to one or more of the three.', 'detail': 'Exam scenarios usually name a symptom (data leaked, record silently changed, service down) and expect you to name the property that failed, then pick the control for that property.'},
    {'id': 'f2', 'cat': 'csslpConcepts', 'front': 'Authentication, authorization and accountability', 'back': 'Authentication proves who or what is making a request, authorization decides what that identity may do, and accountability (auditing) records what it actually did so actions can be traced back to it. They are separate steps and one does not imply the next.', 'detail': 'A classic trap is treating a valid login as permission; being authenticated says nothing about being authorized for a specific record or function.'},
    {'id': 'f3', 'cat': 'csslpConcepts', 'front': 'Non-repudiation', 'back': 'Non-repudiation is assurance that a party cannot credibly deny having performed an action such as sending a message or approving a transaction. In software it is typically built from strong authentication, digital signatures and tamper-evident audit logs.', 'detail': 'Encryption alone does not give non-repudiation; a shared symmetric key cannot show which of the two holders acted, whereas an asymmetric digital signature can.'},
    {'id': 'f4', 'cat': 'csslpConcepts', 'front': 'Least privilege', 'back': 'Every user, process and component should be given only the access it needs to do its job, for only as long as it needs it. This limits the damage from mistakes, bugs and compromise.', 'detail': 'Applies to code too: a web service running as an administrator or with a database owner account violates it even if no user is over-privileged.'},
    {'id': 'f5', 'cat': 'csslpConcepts', 'front': 'Separation of duties', 'back': 'No single person should be able to complete a sensitive process end to end, so critical tasks are split among people or roles (for example, the developer who writes code is not the one who approves its release to production). It makes fraud and undetected error require collusion.', 'detail': 'Often confused with least privilege: separation of duties splits one sensitive process across roles, while least privilege trims each role to the minimum.'},
    {'id': 'f6', 'cat': 'csslpConcepts', 'front': 'Defense in depth', 'back': 'Defense in depth layers independent controls (for example, input validation, authorization checks, encryption and monitoring) so that if one layer fails another still protects the asset. No single control is trusted to be perfect.', 'detail': 'The key word is independent: two layers that share the same flaw or the same credential add little. Do not confuse it with simply buying more tools.'},
    {'id': 'f7', 'cat': 'csslpConcepts', 'front': 'Fail-safe defaults (fail secure)', 'back': 'Access decisions should default to denial, and a component that fails or errors should land in a secure state rather than an open one. Permission is granted explicitly instead of excluded explicitly.', 'detail': 'Fail secure protects data (lock on failure), while fail safe protects human life (unlock on fire alarm). Exams usually mean fail secure for software.'},
    {'id': 'f8', 'cat': 'csslpConcepts', 'front': 'Complete mediation', 'back': 'Every access to every object must be checked for authority, every time, rather than checking once and caching the result. Without it, a permission that is revoked or changed can still be used.', 'detail': 'A typical violation is checking authorization only in the user interface or only when a session starts while the underlying API or later requests are unchecked.'},
    {'id': 'f9', 'cat': 'csslpConcepts', 'front': 'Economy of mechanism', 'back': 'Security mechanisms should be as simple and small as possible, because simple designs are easier to understand, verify and test than complex ones. Complexity is the enemy of security.', 'detail': 'Sometimes called keep it simple; it explains why a small, well-reviewed security component beats a sprawling custom framework.'},
    {'id': 'f10', 'cat': 'csslpConcepts', 'front': 'Open design', 'back': 'The security of a system should not depend on keeping its design or algorithms secret, only on protecting keys and other secrets. Designs that rely on obscurity fail once the design leaks, which it eventually does.', 'detail': 'This is Kerckhoffs principle applied to software: use public, peer-reviewed algorithms and keep only the key secret. Obscurity may be a thin extra layer, never the foundation.'},
    {'id': 'f11', 'cat': 'csslpConcepts', 'front': 'Psychological acceptability', 'back': 'Security mechanisms must be easy enough to use that people apply them correctly and do not bypass them. If a control makes the job hard, users will find a workaround that defeats it.', 'detail': 'Appears when a scenario describes users writing down passwords or disabling a prompt; the better answer redesigns the control rather than scolding the users.'},
    {'id': 'f12', 'cat': 'csslpConcepts', 'front': 'Threat, vulnerability and risk', 'back': 'A threat is a potential cause of harm, a vulnerability is a weakness that a threat can exploit, and risk is the likelihood and impact of a threat exploiting a vulnerability. Without all three there is no meaningful risk.', 'detail': 'Fixing a vulnerability reduces risk but does not remove the threat; a threat with no exploitable vulnerability produces little or no risk.'},
    {'id': 'f13', 'cat': 'csslpConcepts', 'front': 'Risk treatment options', 'back': 'Risk can be mitigated (reduced with controls), transferred (shifted by insurance or contract), avoided (by dropping the risky activity or feature) or accepted (knowingly tolerated within appetite). The choice depends on cost versus impact and on the organization appetite.', 'detail': 'Acceptance is a decision made by the accountable business owner after being informed, not a default that happens when nobody acts, and not a way to ignore the risk.'},
    {'id': 'f14', 'cat': 'csslpConcepts', 'front': 'Annualized loss expectancy (ALE)', 'back': 'ALE is the expected yearly loss from a risk, calculated as single loss expectancy multiplied by annualized rate of occurrence. A control is cost-justified when the reduction in ALE exceeds the annual cost of the control.', 'detail': 'Single loss expectancy is asset value times exposure factor. Questions often give three numbers and ask which one is missing or whether a safeguard is worth buying.'},
    {'id': 'f15', 'cat': 'csslpConcepts', 'front': 'Privacy by design', 'back': 'Privacy by design builds privacy protection into systems from the start, not as an add-on: collect only what is needed, make privacy the default setting, and keep protection throughout the data lifecycle. GDPR calls the legal duty data protection by design and by default.', 'detail': 'Retrofitting consent screens late in development is the opposite of it; the early-requirements answer is usually the correct one.'},
    {'id': 'f16', 'cat': 'csslpConcepts', 'front': 'Secure by design and secure by default', 'back': 'Secure by design means the vendor takes ownership of customer security outcomes by building security into architecture and engineering, and secure by default means the product ships already hardened without customers having to configure protections. CISA promotes both as manufacturer responsibilities.', 'detail': 'The contrast is with shipping an insecure default configuration and publishing a hardening guide, which pushes the burden onto the customer.'},
    {'id': 'f17', 'cat': 'csslpLifecycle', 'front': 'Secure software development lifecycle (secure SDLC) and shift left', 'back': 'A secure SDLC integrates security activities such as requirements, threat modeling, secure coding, testing and review into every phase of development instead of testing security at the end. Shift left means finding and fixing defects as early as possible, when they cost the least to correct.', 'detail': 'The cost of fixing a flaw rises steeply the later it is found, which is the standard justification for earlier security activities in any exam answer.'},
    {'id': 'f18', 'cat': 'csslpLifecycle', 'front': 'Microsoft Security Development Lifecycle (SDL)', 'back': 'The Microsoft SDL is a set of security practices grouped around training, requirements, design, implementation, verification, release and response, and is a prescriptive model that teams adopt to build more secure software. It popularized threat modeling and the STRIDE method.', 'detail': 'SDL is a prescriptive process, whereas BSIMM is a descriptive measurement of what firms already do.'},
    {'id': 'f19', 'cat': 'csslpLifecycle', 'front': 'NIST Secure Software Development Framework (SSDF, SP 800-218)', 'back': 'The SSDF is a set of high-level secure development practices organized into four groups: Prepare the Organization, Protect the Software, Produce Well-Secured Software and Respond to Vulnerabilities. It is outcome-based and works with any SDLC model, and US federal software acquisition draws on it.', 'detail': 'Remember the four groups by their verbs: prepare, protect, produce, respond. It describes what to achieve, not a step-by-step methodology.'},
    {'id': 'f20', 'cat': 'csslpLifecycle', 'front': 'OWASP Software Assurance Maturity Model (SAMM)', 'back': 'SAMM is an open, prescriptive maturity model with five business functions (Governance, Design, Implementation, Verification, Operations), each with three security practices and three maturity levels. Organizations assess where they are and plan a roadmap tailored to their own risk.', 'detail': 'It is used to measure and improve a program deliberately, in contrast to BSIMM, which reports what peers are observed doing.'},
    {'id': 'f21', 'cat': 'csslpLifecycle', 'front': 'Building Security In Maturity Model (BSIMM)', 'back': 'BSIMM is a descriptive model built from observing the real software security initiatives of many organizations, organized into practices and activities across four domains: Governance, Intelligence, SSDL Touchpoints and Deployment. It lets a firm compare itself with peers in its industry.', 'detail': 'Descriptive versus prescriptive is the standard contrast: BSIMM says what others do, SAMM and SDL say what you should do.'},
    {'id': 'f22', 'cat': 'csslpLifecycle', 'front': 'Waterfall, agile and DevOps security implications', 'back': 'Waterfall has distinct phases so security activities map to phase gates, while agile and DevOps iterate quickly so security must be embedded in short cycles through user-story acceptance criteria, automated tests and continuous feedback. The security goals are the same; only the scheduling and automation differ.', 'detail': 'A wrong answer typically proposes a one-time security review at the end of a sprint-based project; the better one automates checks in each iteration.'},
    {'id': 'f23', 'cat': 'csslpLifecycle', 'front': 'DevSecOps', 'back': 'DevSecOps extends DevOps by making security a shared responsibility and automating security checks, such as static analysis, dependency scanning and policy checks, into the continuous integration and delivery pipeline. It aims to keep release speed without releasing unchecked code.', 'detail': 'The point is automation plus shared ownership, not adding a separate security team that blocks the pipeline at the end.'},
    {'id': 'f24', 'cat': 'csslpLifecycle', 'front': 'Security champions', 'back': 'Security champions are developers or team members who take on extra security responsibility within their own teams, acting as a local point of contact, promoting secure practices and helping triage issues. They scale a small central security team across many product teams.', 'detail': 'Champions are not a replacement for the security team and do not own approvals; they are a community-building and early-detection mechanism.'},
    {'id': 'f25', 'cat': 'csslpLifecycle', 'front': 'Process maturity models (CMMI and SSE-CMM)', 'back': 'Maturity models describe how repeatable and managed a process is, from ad hoc work up to optimizing, using levels. The Systems Security Engineering Capability Maturity Model (SSE-CMM, ISO/IEC 21827) applies the idea specifically to security engineering processes.', 'detail': 'A higher level means the process is defined, measured and improved, not that the software is guaranteed secure.'},
    {'id': 'f26', 'cat': 'csslpLifecycle', 'front': 'Security gates and quality gates', 'back': 'A gate is a checkpoint where defined security criteria must be met before work moves to the next phase or release, such as completed threat model, no open critical findings or a passed scan. Automated pipeline gates apply the same idea to builds.', 'detail': 'Gates should be based on risk-based criteria; a gate that anyone can routinely override or that has no clear criteria provides no real control.'},
    {'id': 'f27', 'cat': 'csslpLifecycle', 'front': 'Change management and the change advisory (control) board', 'back': 'Change management ensures changes to requirements, code and environments are requested, assessed for impact including security, approved, tested and recorded before they are made. A change control board approves significant changes and keeps the baseline trustworthy.', 'detail': 'Security impact analysis is part of every change request; emergency changes are still documented and reviewed afterward rather than skipping the process altogether.'},
    {'id': 'f28', 'cat': 'csslpLifecycle', 'front': 'Software security metrics', 'back': 'Security metrics such as defect density, percentage of code covered by scanning, time to remediate vulnerabilities and number of open findings by severity show whether the program works and where to improve. Good metrics are tied to goals and trend over time.', 'detail': 'A count of vulnerabilities found can reflect better testing, not worse code; look for trends and mean time to fix rather than a single raw number.'},
    {'id': 'f29', 'cat': 'csslpLifecycle', 'front': 'Role-based security training', 'back': 'Developers, testers, architects, product owners and operators need different security knowledge, so training is tailored to each role and refreshed regularly. It supports the Prepare the Organization group of the SSDF and the training practice of the SDL.', 'detail': 'One generic annual awareness video does not satisfy a role-based requirement; a developer needs secure coding, an architect needs threat modeling.'},
    {'id': 'f30', 'cat': 'csslpLifecycle', 'front': 'Policy, standard, guideline and procedure hierarchy', 'back': 'A policy states management intent and is mandatory and high level, a standard sets specific mandatory requirements, a guideline gives recommended but optional advice, and a procedure lists the step-by-step actions. Together they translate governance into practice.', 'detail': 'Tested by asking which document is mandatory and technology-specific (standard) versus optional (guideline).'},
    {'id': 'f31', 'cat': 'csslpReq', 'front': 'Functional and non-functional (security) requirements', 'back': 'Functional requirements describe what the software must do, while non-functional requirements describe qualities such as performance, availability and security. Security requirements are mostly non-functional constraints, but some, such as a login feature, are also functional.', 'detail': 'If security requirements are missing from the specification, nobody builds or tests them; the first move is to elicit and document them.'},
    {'id': 'f32', 'cat': 'csslpReq', 'front': 'Security requirements traceability matrix (SRTM)', 'back': 'An SRTM maps each security requirement to its source, design element, implementation and test case, so the team can show that every requirement was built and verified. It also shows which controls are affected when a requirement changes.', 'detail': 'Traceability works in both directions: from requirement to test for coverage, and from test back to requirement to justify why the test exists.'},
    {'id': 'f33', 'cat': 'csslpReq', 'front': 'Abuse case and misuse case', 'back': 'A misuse or abuse case describes how an attacker or careless user could deliberately make the system behave badly, written as the opposite of a use case. They are used to discover security requirements and to build negative tests.', 'detail': 'Use cases say what the system should do; abuse cases say what must not be possible and drive requirements like lockout and rate limits.'},
    {'id': 'f34', 'cat': 'csslpReq', 'front': 'Data classification', 'back': 'Data classification assigns data to levels such as public, internal, confidential and restricted based on sensitivity and the impact of disclosure. The level drives requirements for encryption, access control, retention, logging and handling.', 'detail': 'Classification is done first by the data owner and drives controls; it is not decided by the developer or by what is cheapest to protect.'},
    {'id': 'f35', 'cat': 'csslpReq', 'front': 'Data lifecycle', 'back': 'The data lifecycle runs from creation or collection through storage, use, sharing and archival to destruction, and security and privacy requirements must cover every stage. Data is often most exposed in transit and at disposal.', 'detail': 'Requirements that stop at storage miss archival copies, backups and test environments, which are common sources of leaks.'},
    {'id': 'f36', 'cat': 'csslpReq', 'front': 'Data minimization and purpose limitation', 'back': 'Data minimization means collecting and keeping only the personal data actually needed, and purpose limitation means using it only for the purpose stated when it was collected. Data never collected cannot be breached.', 'detail': 'The best requirement for risky data you do not need is usually not to collect it, ahead of encrypting it.'},
    {'id': 'f37', 'cat': 'csslpReq', 'front': 'Privacy impact assessment (PIA) and data protection impact assessment (DPIA)', 'back': 'A privacy impact assessment analyzes how a system collects, uses, shares and protects personal data and identifies privacy risks to individuals and the controls to reduce them. Under GDPR a DPIA is mandatory for processing likely to result in high risk to individuals.', 'detail': 'Do it during requirements and design, before launch, so that findings can change the design cheaply.'},
    {'id': 'f38', 'cat': 'csslpReq', 'front': 'Personally identifiable information (PII)', 'back': 'PII is information that can identify a person directly or when combined with other data, such as name, government identifier, biometric record or precise location. Laws define personal data differently, but all require extra care in handling it.', 'detail': 'Pseudonymized data can often still be re-identified and is generally still regulated, while truly anonymized data is not.'},
    {'id': 'f39', 'cat': 'csslpReq', 'front': 'Regulatory and compliance requirements (GDPR, HIPAA, PCI DSS, SOX)', 'back': 'Software must meet the laws, regulations and contractual standards that apply to its data and market, for example GDPR for personal data of people in the EU, HIPAA for US health information, PCI DSS for payment cards and SOX for financial reporting controls. Requirements work begins by identifying which apply.', 'detail': 'PCI DSS is an industry contractual standard, not a law, but non-compliance still has real consequences such as fines and loss of card processing.'},
    {'id': 'f40', 'cat': 'csslpReq', 'front': 'FIPS 199 security categorization', 'back': 'FIPS 199 rates the potential impact of loss of confidentiality, integrity and availability as low, moderate or high for an information type or system, and the highest rating drives the baseline of controls. This is the first step in the NIST risk management approach.', 'detail': 'The system takes the high-water mark: one high impact on any of the three properties makes the overall category high.'},
    {'id': 'f41', 'cat': 'csslpReq', 'front': 'Security user stories and acceptance criteria', 'back': 'In agile development, security is captured as user stories or as acceptance criteria and a definition of done attached to every story, for example that all inputs are validated and access is checked. This makes security requirements testable inside each sprint.', 'detail': 'A vague story like the system must be secure cannot be tested; the answer with a measurable criterion is better.'},
    {'id': 'f42', 'cat': 'csslpReq', 'front': 'Identity and access requirements (RBAC and ABAC)', 'back': 'Role-based access control grants permissions through roles tied to job functions, while attribute-based access control decides using attributes of the user, resource and context such as department, time or device. Requirements should say which model and which roles or rules apply.', 'detail': 'RBAC is simpler to administer; ABAC is more flexible and fine-grained but harder to audit and reason about.'},
    {'id': 'f43', 'cat': 'csslpReq', 'front': 'Audit and logging requirements', 'back': 'Requirements should state which security-relevant events must be logged (such as logins, access failures, privilege changes and data exports), what details to record, how long to keep logs and how to protect them from tampering. Sensitive data such as passwords must never be written to logs.', 'detail': 'Logging requirements support accountability and incident response, and they must be defined early since retrofitting them is costly.'},
    {'id': 'f44', 'cat': 'csslpReq', 'front': 'Recovery time objective (RTO) and recovery point objective (RPO)', 'back': 'RTO is the maximum acceptable time to restore a service after disruption, and RPO is the maximum acceptable amount of data loss measured in time. Availability and resilience requirements are derived from these targets.', 'detail': 'RTO is about time to recover; RPO is about how far back the restored data may be. They are set by the business, not by IT.'},
    {'id': 'f45', 'cat': 'csslpReq', 'front': 'Data retention and disposal requirements', 'back': 'Retention requirements say how long data must be kept to satisfy law and business need, and disposal requirements say how it is securely destroyed afterward. Keeping data longer than needed raises breach impact and can violate privacy law.', 'detail': 'Retention and the right to erasure can conflict, so requirements must say which data is kept for legal reasons and which must be deleted on request.'},
    {'id': 'f46', 'cat': 'csslpReq', 'front': 'OWASP Application Security Verification Standard (ASVS)', 'back': 'ASVS is a catalog of testable application security requirements with three verification levels, from baseline (level 1) to the highest assurance for critical applications (level 3). Teams use it as a source of requirements and as a basis for testing and procurement.', 'detail': 'The level is chosen by the risk of the application; level 3 is for the most sensitive applications, not a default for everything.'},
    {'id': 'f47', 'cat': 'csslpDesign', 'front': 'Threat modeling', 'back': 'Threat modeling is a structured way to identify what could go wrong with a system, decide how serious each threat is and choose mitigations, ideally during design. A basic version asks what we are building, what can go wrong, what we will do about it and whether we did a good job.', 'detail': 'It is done early and repeated whenever the design changes; a threat model made once and filed away goes stale.'},
    {'id': 'f48', 'cat': 'csslpDesign', 'front': 'STRIDE', 'back': 'STRIDE categorizes threats as Spoofing, Tampering, Repudiation, Information disclosure, Denial of service and Elevation of privilege. Each maps to a violated property: authentication, integrity, non-repudiation, confidentiality, availability and authorization.', 'detail': 'Used by walking each element of a data flow diagram through the six categories. STRIDE finds threats; it does not rank them.'},
    {'id': 'f49', 'cat': 'csslpDesign', 'front': 'DREAD', 'back': 'DREAD is a scheme for rating threat severity by scoring Damage potential, Reproducibility, Exploitability, Affected users and Discoverability. The scores are combined into a ranking used to prioritize which threats to address first.', 'detail': 'Remember that STRIDE classifies and DREAD ranks; DREAD is subjective and has been dropped by some of its originators, but it remains in exam material.'},
    {'id': 'f50', 'cat': 'csslpDesign', 'front': 'PASTA', 'back': 'PASTA, the Process for Attack Simulation and Threat Analysis, is a seven-stage risk-centric threat modeling method that starts from business objectives and technical scope and ends with risk analysis and countermeasures. It connects threats to business impact through attack simulation.', 'detail': 'Pick PASTA when the question stresses business risk and attacker simulation; pick STRIDE when it stresses categories of technical threat per element.'},
    {'id': 'f51', 'cat': 'csslpDesign', 'front': 'Attack tree', 'back': 'An attack tree shows an attacker goal as the root and the different ways to reach it as branches, with AND and OR nodes and often a cost or probability on each path. It reveals the cheapest or likeliest path an attacker would choose.', 'detail': 'Attack trees begin from the attacker goal and work downward, while a data flow diagram starts from the system and its components.'},
    {'id': 'f52', 'cat': 'csslpDesign', 'front': 'Data flow diagram (DFD) and trust boundaries', 'back': 'A data flow diagram shows processes, data stores, external entities and the flows between them, and trust boundaries mark where data crosses between zones of different trust or privilege. Threats concentrate where flows cross trust boundaries.', 'detail': 'When asked where to look first in a design for threats, the answer is the points where data crosses a trust boundary.'},
    {'id': 'f53', 'cat': 'csslpDesign', 'front': 'Attack surface analysis and reduction', 'back': 'The attack surface is the sum of all the entry points, interfaces and data an attacker could reach, and reducing it means removing unneeded features, ports, accounts and code. Less exposed surface means fewer places to attack and to defend.', 'detail': 'Disabling an unused feature beats trying to harden it; code that is not shipped cannot be exploited.'},
    {'id': 'f54', 'cat': 'csslpDesign', 'front': 'Zero trust architecture (NIST SP 800-207)', 'back': 'Zero trust assumes no implicit trust based on network location and requires every request to be authenticated, authorized and continuously evaluated using identity, device state and context. A policy decision point decides and a policy enforcement point applies the decision at each resource.', 'detail': 'Being inside the corporate network grants nothing; this principle is often tested against a perimeter-only or VPN-only design.'},
    {'id': 'f55', 'cat': 'csslpDesign', 'front': 'Least common mechanism', 'back': 'Mechanisms shared among many users or components should be minimized, because shared resources create paths for information to leak or for one party failure to affect others. Designs should isolate components rather than share state.', 'detail': 'It is the reason multi-tenant systems isolate tenant data and why shared global variables or temp files are risky.'},
    {'id': 'f56', 'cat': 'csslpDesign', 'front': 'Microservices security design', 'back': 'Microservices need strong service-to-service authentication (often mutual TLS), authorization at each service, an API gateway as a controlled entry point, secrets handled outside the code and centralized logging. The many network paths mean the old trusted internal network assumption no longer holds.', 'detail': 'Authorization checks are needed in every service, not just at the gateway, or an attacker who gets inside can call services directly.'},
    {'id': 'f57', 'cat': 'csslpDesign', 'front': 'API security design', 'back': 'Secure APIs authenticate every caller, authorize at the object and function level, validate input against a schema, limit rates and avoid exposing excess data. The top OWASP API risk is broken object level authorization, where a caller changes an identifier to reach someone else data.', 'detail': 'Hiding an identifier behind a long random value does not replace an actual authorization check on the object.'},
    {'id': 'f58', 'cat': 'csslpDesign', 'front': 'Shared responsibility model in cloud', 'back': 'In cloud computing the provider secures the underlying infrastructure and the customer secures what they put on it, with the split depending on the service model: the customer owns more in infrastructure as a service and less in software as a service. Data, identities and configuration are always the customer responsibility.', 'detail': 'Misconfigured storage buckets are a customer-side failure, not the provider, which is the standard example for this concept.'},
    {'id': 'f59', 'cat': 'csslpDesign', 'front': 'Container and orchestration security design', 'back': 'Secure container design uses minimal trusted base images, scans images, runs as a non-root user with limited capabilities, keeps secrets out of images, and applies network policies and role-based access control in the orchestrator. Containers share the host kernel so isolation is weaker than virtual machines.', 'detail': 'The image is immutable and replaced rather than patched in place, so fixing a vulnerability means rebuilding and redeploying the image.'},
    {'id': 'f60', 'cat': 'csslpDesign', 'front': 'Serverless security considerations', 'back': 'In serverless computing the provider manages the servers, so the developer focuses on securing function code, event inputs, dependencies, narrowly scoped identity permissions and secrets. Every event source is an input that must be validated.', 'detail': 'Per-function least privilege is the key control; one over-broad role shared by every function gives an attacker the keys to everything.'},
    {'id': 'f61', 'cat': 'csslpDesign', 'front': 'Secure design patterns', 'back': 'Security design patterns are reusable solutions to common design problems, such as a reference monitor or single access point that mediates all access, input guards, secure logger and role-based access control. Using proven patterns avoids reinventing flawed security.', 'detail': 'The reference monitor concept is tied to complete mediation: always invoked, tamper-proof and small enough to verify.'},
    {'id': 'f62', 'cat': 'csslpDesign', 'front': 'Federated identity and single sign-on (SAML, OIDC, OAuth 2.0)', 'back': 'Federation lets one trusted identity provider authenticate users for many applications. SAML and OpenID Connect carry authentication, and OAuth 2.0 is an authorization framework for delegated access to resources; OpenID Connect adds an identity layer on top of OAuth 2.0.', 'detail': 'OAuth 2.0 by itself is authorization, not authentication; that distinction appears often.'},
    {'id': 'f63', 'cat': 'csslpDesign', 'front': 'Cryptographic architecture and key management', 'back': 'Design should use vetted algorithms and libraries, protect data in transit, at rest and where needed in use, and manage the whole key lifecycle: generation, storage, rotation, revocation and destruction. Keys are best held in a hardware security module or managed key service, separate from the data.', 'detail': 'Strong encryption with keys stored next to the data or in the code gives little protection. Crypto agility, the ability to change algorithms, is a design goal.'},
    {'id': 'f64', 'cat': 'csslpDesign', 'front': 'Security design review and architecture risk analysis', 'back': 'A design review examines the architecture against security requirements and principles, checking trust boundaries, authentication, authorization, data protection and failure handling before coding begins. Findings are tracked to resolution and feed the threat model.', 'detail': 'Design flaws are the most expensive to fix later; this review is where insecure design (an OWASP category) is caught.'},
    {'id': 'f65', 'cat': 'csslpDesign', 'front': 'AI and machine learning system security considerations', 'back': 'AI-enabled software adds threats such as prompt injection, training-data poisoning, model theft, leakage of sensitive data through outputs and over-trusting model output that drives actions. Design controls include input and output filtering, least-privilege tool access, human approval for high-impact actions and provenance of training data.', 'detail': 'The OWASP Top 10 for LLM Applications and NIST AI RMF catalog these; treat model output as untrusted input to downstream systems.'},
    {'id': 'f66', 'cat': 'csslpDesign', 'front': 'Data protection by design: at rest, in transit and in use', 'back': 'Sensitive data should be protected wherever it exists: encrypted in storage, encrypted on the network with current TLS, and, for the most sensitive cases, protected while processed using techniques such as tokenization, masking or confidential computing. Which control to use depends on classification.', 'detail': 'Tokenization replaces a value with a surrogate and keeps the real value in a vault, reducing how many systems fall under compliance scope.'},
    {'id': 'f67', 'cat': 'csslpImpl', 'front': 'Input validation (allow-list)', 'back': 'Input validation checks that data is of the expected type, length, range and format before it is used, and it is most reliable as an allow-list of what is acceptable rather than a block-list of known bad values. It must happen on the server side, because client-side checks are easily bypassed.', 'detail': 'Validation reduces attack surface but is not a complete defense against injection; it pairs with parameterization and output encoding.'},
    {'id': 'f68', 'cat': 'csslpImpl', 'front': 'Output encoding', 'back': 'Output encoding converts data into a safe form for the context in which it will be displayed or interpreted, such as HTML body, attribute, JavaScript or URL, so that it is treated as text and not as code. It is the primary defense against cross-site scripting.', 'detail': 'Encoding must match the output context; HTML encoding does not protect data that is placed inside a JavaScript string.'},
    {'id': 'f69', 'cat': 'csslpImpl', 'front': 'Parameterized queries and SQL injection', 'back': 'SQL injection occurs when untrusted input is concatenated into a query so that it changes the query structure. Parameterized queries (prepared statements) keep code and data separate so input is always treated as a value, which is the preferred defense.', 'detail': 'Escaping and stored procedures built with string concatenation are weaker than true parameterization; least privilege on the database account limits damage.'},
    {'id': 'f70', 'cat': 'csslpImpl', 'front': 'Cross-site scripting (XSS)', 'back': 'XSS lets an attacker get a victim browser to run attacker-supplied script in the context of a trusted site, in stored, reflected or DOM-based forms. Defenses are context-aware output encoding, input validation, and a content security policy as a backstop.', 'detail': 'Stored XSS persists on the server and hits every viewer; reflected XSS needs the victim to follow a crafted link.'},
    {'id': 'f71', 'cat': 'csslpImpl', 'front': 'Cross-site request forgery (CSRF)', 'back': 'CSRF tricks a logged-in user browser into sending an unwanted state-changing request to a site that trusts the browser cookies. Defenses are anti-forgery tokens, SameSite cookie attributes and requiring re-authentication for sensitive actions.', 'detail': 'XSS abuses the site trust in the browser content; CSRF abuses the site trust in the browser requests. Do not confuse the two.'},
    {'id': 'f72', 'cat': 'csslpImpl', 'front': 'Broken access control and insecure direct object reference (IDOR)', 'back': 'Broken access control means users can act outside their intended permissions, for example by changing an identifier in a URL to read another account. It is the top category in the OWASP Top 10, and the fix is server-side authorization checks on every request, enforced by default deny.', 'detail': 'Hiding a link in the interface is not access control; the server must check authorization for the specific object each time.'},
    {'id': 'f73', 'cat': 'csslpImpl', 'front': 'Server-side request forgery (SSRF)', 'back': 'SSRF makes a server send requests to a destination chosen by the attacker, often reaching internal services or cloud metadata endpoints that the attacker could not reach directly. Defenses include allow-listing destinations, blocking internal address ranges and restricting the server network egress.', 'detail': 'It was its own OWASP Top 10 category in 2021 and is now treated under broken access control in the 2025 list.'},
    {'id': 'f74', 'cat': 'csslpImpl', 'front': 'Buffer overflow', 'back': 'A buffer overflow happens when a program writes more data into a fixed-size memory buffer than it can hold, overwriting adjacent memory and potentially letting an attacker run code. Prevention includes bounds checking, safe functions, memory-safe languages, stack canaries, data execution prevention and address space layout randomization.', 'detail': 'Mitigations such as canaries and ASLR make exploitation harder but do not remove the bug; fixing the code or changing language does.'},
    {'id': 'f75', 'cat': 'csslpImpl', 'front': 'Use-after-free and memory safety', 'back': 'Use-after-free occurs when a program continues to use memory after it has been released, which can allow data corruption or code execution. Memory-safe languages such as Rust, Go, C# and Java prevent whole classes of these flaws, and government agencies encourage moving to them.', 'detail': 'Memory-safety errors are consistently a large share of serious vulnerabilities in C and C++ codebases.'},
    {'id': 'f76', 'cat': 'csslpImpl', 'front': 'Race condition and TOCTOU', 'back': 'A race condition is a flaw where the outcome depends on the timing of concurrent operations, and time-of-check to time-of-use (TOCTOU) is the case where state changes between a security check and the later use. Fixes include atomic operations, locking and checking and acting on the same handle.', 'detail': 'A file permission check followed by a separate file open is the textbook TOCTOU example.'},
    {'id': 'f77', 'cat': 'csslpImpl', 'front': 'Secure error handling and logging', 'back': 'Applications should fail securely, show users generic error messages and write detailed diagnostics to protected logs, never revealing stack traces, queries or system details to users. Logs must not contain secrets or sensitive personal data and must be protected from tampering and log injection.', 'detail': 'Verbose error messages are an information disclosure that helps attackers map the system; the answer is generic to the user, detailed in the log.'},
    {'id': 'f78', 'cat': 'csslpImpl', 'front': 'Cryptography usage in code', 'back': 'Use well-vetted libraries and current algorithms, never invent your own, generate random values with a cryptographically secure generator, and store passwords with a slow salted hash such as Argon2id, bcrypt, scrypt or PBKDF2. Hard-coded keys and outdated algorithms such as MD5 or SHA-1 for security purposes are defects.', 'detail': 'Passwords are hashed, not encrypted, because there is no need to ever recover them; fast general hashes make guessing cheap.'},
    {'id': 'f79', 'cat': 'csslpImpl', 'front': 'Secrets management', 'back': 'Secrets such as passwords, API keys and certificates must be kept out of source code, images and logs and held in a dedicated secrets manager with access control, rotation and audit. Detection tools scan repositories for leaked secrets.', 'detail': 'A secret committed to a repository must be treated as compromised and rotated even if the commit is deleted, since history and clones keep it.'},
    {'id': 'f80', 'cat': 'csslpImpl', 'front': 'Secure code review', 'back': 'Secure code review examines source code for security flaws, using a mix of manual peer review against checklists and automated tools, focusing on high-risk areas such as authentication, input handling and cryptography. It finds logic flaws that scanners miss.', 'detail': 'Automated tools find patterns at scale and humans find design and business-logic flaws; the strongest answer usually combines both.'},
    {'id': 'f81', 'cat': 'csslpImpl', 'front': 'Secure configuration and hardening', 'back': 'Hardening removes unneeded services, accounts and features, changes default credentials, applies least privilege and sets secure configuration to an approved baseline such as a CIS Benchmark. Security misconfiguration is among the most common weaknesses.', 'detail': 'Default credentials and verbose debug modes left enabled in production are the standard examples of misconfiguration.'},
    {'id': 'f82', 'cat': 'csslpImpl', 'front': 'Source code control security', 'back': 'Protect the repository with strong authentication, least-privilege access, branch protection that requires reviewed pull requests, signed commits and an audit trail of changes. The repository is a high-value target because whatever is committed gets built and shipped.', 'detail': 'Requiring a second reviewer for merges enforces separation of duties and defends against a single compromised developer account.'},
    {'id': 'f83', 'cat': 'csslpImpl', 'front': 'OWASP Top 10', 'back': 'The OWASP Top 10 is an awareness list of the most critical web application security risks; broken access control has been first in both the 2021 and 2025 editions. The 2025 edition lists, among others, security misconfiguration, software supply chain failures, cryptographic failures, injection and insecure design.', 'detail': 'It is a list of risk categories for awareness, not a complete standard; use ASVS when you need verifiable requirements.'},
    {'id': 'f84', 'cat': 'csslpImpl', 'front': 'Common Weakness Enumeration (CWE)', 'back': 'CWE is a community catalog of software and hardware weakness types, such as improper input validation or use of hard-coded credentials, identified by CWE numbers. It classifies the underlying flaw, while CVE identifies a specific vulnerability in a specific product.', 'detail': 'Weakness (CWE) is the type of mistake; vulnerability (CVE) is a particular instance in a product; CAPEC catalogs attack patterns.'},
    {'id': 'f85', 'cat': 'csslpTest', 'front': 'Static application security testing (SAST)', 'back': 'SAST analyzes source code, bytecode or binaries without running the application to find flaws such as injection patterns and hard-coded secrets. It works early in the lifecycle and pinpoints the line of code, but can produce false positives and cannot see runtime or configuration issues.', 'detail': 'White-box and early: the choice when the question says source code is available and the goal is to find flaws before the build runs.'},
    {'id': 'f86', 'cat': 'csslpTest', 'front': 'Dynamic application security testing (DAST)', 'back': 'DAST tests a running application from the outside by sending crafted requests and observing responses, much like an attacker, without needing source code. It finds runtime and configuration issues, but it cannot point to the line of code and covers only the paths it reaches.', 'detail': 'Black-box and later in the lifecycle: the choice for a deployed or staging application with no source access.'},
    {'id': 'f87', 'cat': 'csslpTest', 'front': 'Interactive application security testing (IAST)', 'back': 'IAST uses agents or sensors inside the running application while it is exercised by tests, combining insight into the code with runtime behavior to give accurate findings with fewer false positives. It needs the application to be running with test traffic.', 'detail': 'IAST sees only the code paths the tests exercise, so coverage depends on the quality of the functional tests.'},
    {'id': 'f88', 'cat': 'csslpTest', 'front': 'Runtime application self-protection (RASP)', 'back': 'RASP embeds protection inside the application runtime to detect and block attacks as they happen, using knowledge of the application own context. It is a protective control used in production, not primarily a testing technique.', 'detail': 'A web application firewall sits outside the application at the network edge, whereas RASP lives inside it.'},
    {'id': 'f89', 'cat': 'csslpTest', 'front': 'Fuzz testing (fuzzing)', 'back': 'Fuzzing feeds large amounts of malformed, unexpected or random input to a program to trigger crashes, hangs and memory errors that reveal vulnerabilities. Coverage-guided fuzzers evolve inputs to reach more code, and fuzzing is especially effective on parsers and protocol handlers.', 'detail': 'It is the best technique for finding unknown input-handling and memory-safety flaws; it is automated and needs no knowledge of the code.'},
    {'id': 'f90', 'cat': 'csslpTest', 'front': 'Penetration testing', 'back': 'A penetration test is an authorized, time-boxed simulated attack that actively exploits vulnerabilities to show real impact. It validates that controls work together and is performed by skilled testers, often from an independent party.', 'detail': 'A vulnerability scan lists potential weaknesses, whereas a pen test proves exploitability by actually exploiting them.'},
    {'id': 'f91', 'cat': 'csslpTest', 'front': 'Rules of engagement and testing authorization', 'back': 'Rules of engagement are the written agreement that defines the scope, targets, techniques, schedule, contacts and boundaries of a penetration test, along with authorization from the system owner. Testing without it can be illegal and can cause outages.', 'detail': 'Written authorization comes first; a scope not covered by the agreement must not be tested.'},
    {'id': 'f92', 'cat': 'csslpTest', 'front': 'Code coverage', 'back': 'Code coverage measures how much of the code is executed by tests, for example by statements, branches or paths. It shows what has never been tested but does not prove the tests check the right behavior.', 'detail': 'High coverage with weak assertions gives false comfort; security test cases should cover abuse cases and error paths, not only happy paths.'},
    {'id': 'f93', 'cat': 'csslpTest', 'front': 'Regression testing', 'back': 'Regression testing re-runs existing tests after a change to confirm that fixes and new features did not break previous behavior, including security controls. Automated suites run on every build make this practical.', 'detail': 'Every fixed vulnerability should get a regression test so it cannot silently return.'},
    {'id': 'f94', 'cat': 'csslpTest', 'front': 'Unit, integration, system and acceptance testing', 'back': 'Unit tests check individual components, integration tests check interactions between components, system tests check the whole assembled system against requirements, and user acceptance testing confirms the software meets business needs. Security checks belong at every level.', 'detail': 'Authorization flaws often appear only at integration or system level, where components pass data between trust boundaries.'},
    {'id': 'f95', 'cat': 'csslpTest', 'front': 'Security test plan and test cases from requirements', 'back': 'A security test plan defines what will be tested, how, by whom and with what pass criteria, and it derives its test cases from security requirements, abuse cases and the threat model. Traceability shows every requirement has a test.', 'detail': 'Test cases built only from functional requirements miss security; negative testing of abuse cases is what finds the gaps.'},
    {'id': 'f96', 'cat': 'csslpTest', 'front': 'Negative testing', 'back': 'Negative testing deliberately supplies invalid, unexpected or hostile input and actions to confirm the software rejects them safely, such as boundary values, wrong data types and attempts to skip steps. It checks that the software does not do what it should not do.', 'detail': 'Functional testing proves the right thing works; negative testing proves the wrong thing fails safely.'},
    {'id': 'f97', 'cat': 'csslpTest', 'front': 'Vulnerability scanning versus penetration testing', 'back': 'Vulnerability scanning is an automated, broad and repeatable check for known weaknesses and missing patches, while penetration testing is a manual, goal-driven attempt to exploit weaknesses in combination. Scans suit frequent checks, and pen tests suit periodic deep assurance.', 'detail': 'Scanners produce false positives that need validation; a pen test finding is usually exploited and so is more credible but costly.'},
    {'id': 'f98', 'cat': 'csslpTest', 'front': 'Bug bounty program', 'back': 'A bug bounty program invites outside researchers to find and responsibly report vulnerabilities in exchange for rewards under defined scope and rules. It complements internal testing with many diverse skills but needs triage capacity and a safe harbor policy.', 'detail': 'It does not replace internal testing; a program with no triage process creates a backlog of unresolved reports.'},
    {'id': 'f99', 'cat': 'csslpTest', 'front': 'Test data management and data masking', 'back': 'Test environments should not use real production personal data; use synthetic data or data that has been masked, anonymized or tokenized. Test systems are usually less protected, so real data there creates a breach and compliance risk.', 'detail': 'Copying production into test without masking is a classic privacy finding, even if the test network is internal.'},
    {'id': 'f100', 'cat': 'csslpTest', 'front': 'False positives and false negatives', 'back': 'A false positive is a reported issue that is not real, and a false negative is a real issue the test failed to report. Tools trade one for the other, and false negatives are more dangerous because they create unwarranted confidence.', 'detail': 'Teams that ignore a noisy tool because of false positives may miss real findings; tuning and triage are part of a testing program.'},
    {'id': 'f101', 'cat': 'csslpTest', 'front': 'Security acceptance and test exit criteria', 'back': 'Exit criteria are the predefined conditions that testing must meet before the software can be released, such as no open critical or high vulnerabilities, required scans completed and sign-off from the risk owner. Residual risk that remains is formally accepted by the business owner.', 'detail': 'Releasing on a deadline despite failing criteria requires documented risk acceptance by the accountable owner, not a quiet exception by the project team.'},
    {'id': 'f102', 'cat': 'csslpDeploy', 'front': 'Release management and code signing', 'back': 'Release management controls how software moves into production through approvals, tested builds, versioning and rollback plans. Code signing applies a digital signature to the released artifact so users and systems can verify its origin and that it was not altered.', 'detail': 'A signature proves who published the code and that it is unchanged; it does not prove the code is free of vulnerabilities.'},
    {'id': 'f103', 'cat': 'csslpDeploy', 'front': 'Configuration management and baselines', 'back': 'Configuration management identifies, controls and tracks the configuration items of software and environments, with an approved baseline against which changes and drift are detected. It supports repeatable builds, auditing and fast recovery.', 'detail': 'Unauthorized changes to a baseline are a security signal; the baseline is also the reference for hardening and compliance checks.'},
    {'id': 'f104', 'cat': 'csslpDeploy', 'front': 'Blue-green and canary deployment', 'back': 'In a blue-green deployment two identical environments run, and traffic is switched from the old to the new in one step with easy rollback. A canary deployment sends the new version to a small share of users first and expands only if it behaves well.', 'detail': 'Both reduce deployment risk and allow fast rollback; canary limits exposure of a flaw to a few users.'},
    {'id': 'f105', 'cat': 'csslpDeploy', 'front': 'CI/CD pipeline security', 'back': 'A pipeline builds and ships code, so it must be protected: least-privilege and short-lived credentials, isolated and ephemeral build runners, protected secrets, signed artifacts and logged changes to pipeline definitions. A compromised pipeline lets an attacker insert malicious code that looks legitimate.', 'detail': 'The build system is a prime attack target; the SolarWinds compromise inserted malicious code during the build process, not in the source repository.'},
    {'id': 'f106', 'cat': 'csslpDeploy', 'front': 'Infrastructure as code (IaC) security and drift', 'back': 'Infrastructure as code defines environments in version-controlled files, so security checks can scan templates for misconfigurations before deployment and changes get reviewed. Drift is when the real environment diverges from the code, and is corrected by redeploying from code.', 'detail': 'Scanning IaC templates before deployment catches open storage and permissive rules earlier than finding them in production.'},
    {'id': 'f107', 'cat': 'csslpDeploy', 'front': 'Secure installation and operational readiness', 'back': 'Before go-live, confirm that the software installs with secure defaults, is hardened, has documented and tested operations and recovery procedures, monitoring in place and a signed security acceptance. An operational readiness review gathers these checks.', 'detail': 'Release approval should depend on completed security acceptance, not only on functional sign-off.'},
    {'id': 'f108', 'cat': 'csslpDeploy', 'front': 'Vulnerability management lifecycle', 'back': 'Vulnerability management continuously discovers vulnerabilities, assesses and prioritizes them by severity and context, remediates or mitigates them, verifies the fix and reports. Prioritization uses CVSS severity together with exploitability data such as EPSS and the CISA known exploited vulnerabilities catalog.', 'detail': 'CVSS measures severity, not risk to you; a medium score on an internet-facing, actively exploited flaw may outrank a high score on an isolated system.'},
    {'id': 'f109', 'cat': 'csslpDeploy', 'front': 'Patch management', 'back': 'Patch management identifies, tests, deploys and verifies updates on a risk-based schedule, with an expedited path for actively exploited flaws, and a rollback plan. NIST SP 800-40 frames it as preventive maintenance of the enterprise.', 'detail': 'Testing patches before broad deployment avoids breaking production; compensating controls such as virtual patching bridge the gap when a patch cannot yet be applied.'},
    {'id': 'f110', 'cat': 'csslpDeploy', 'front': 'Incident response for software and coordinated vulnerability disclosure', 'back': 'Software incident response follows prepare, detect and analyze, contain, eradicate and recover, then review lessons learned. Product teams also operate a process to receive vulnerability reports, often via a product security incident response team, and coordinate disclosure with the reporter.', 'detail': 'Preserving evidence and containing the problem come before cleanup; lessons learned feed back into requirements and testing.'},
    {'id': 'f111', 'cat': 'csslpDeploy', 'front': 'Security monitoring and logging operations', 'back': 'Production monitoring collects logs and metrics, centralizes them in a system such as a SIEM, and alerts on suspicious events so incidents are detected quickly. Detection requires that the application writes meaningful security events in the first place.', 'detail': 'Insufficient logging and alerting is itself an OWASP category; attackers often remain undetected for long periods.'},
    {'id': 'f112', 'cat': 'csslpDeploy', 'front': 'Root cause analysis and post-incident review', 'back': 'After an incident or serious defect, the team finds the underlying cause rather than the symptom, records what happened and fixes the process and code so it does not recur. Findings should update requirements, tests and training.', 'detail': 'A good answer fixes the class of problem, for example adding a test and a coding standard, not only the single instance.'},
    {'id': 'f113', 'cat': 'csslpDeploy', 'front': 'Software end of life (EOL) and decommissioning', 'back': 'End of life is when a vendor stops providing support, including security patches, and decommissioning is the planned retirement of the software with notice to users, data migration or archival, access removal and secure data destruction. Running unsupported software leaves known flaws unfixable.', 'detail': 'Plan retirement early; leftover accounts, credentials, DNS entries and data in retired systems are common sources of later compromise.'},
    {'id': 'f114', 'cat': 'csslpDeploy', 'front': 'Data sanitization (NIST SP 800-88)', 'back': 'Media sanitization ensures data cannot be recovered, using clear, purge or destroy methods depending on the sensitivity of the data and the media. Cryptographic erase renders data unreadable by destroying the encryption key.', 'detail': 'Simply deleting files or reformatting is not sanitization; the method must match the sensitivity and whether media will be reused.'},
    {'id': 'f115', 'cat': 'csslpDeploy', 'front': 'Operational security controls: backup, recovery and continuity', 'back': 'Operations maintains tested backups, protected from tampering and ransomware, along with recovery and business continuity plans that meet the RTO and RPO. Software should be designed so that restoring it, and its data, is practical.', 'detail': 'A backup that has never been restored is an unverified assumption; testing recovery is part of operational assurance.'},
    {'id': 'f116', 'cat': 'csslpSupply', 'front': 'Software supply chain attack', 'back': 'A software supply chain attack compromises something a victim trusts, such as a dependency, build system, update mechanism or vendor, to reach the victim downstream. Examples include SolarWinds (build tampering), Log4Shell (a flaw in a widely used library) and the xz Utils backdoor.', 'detail': 'The danger is that the malicious or vulnerable code arrives through a trusted channel and often with a valid signature.'},
    {'id': 'f117', 'cat': 'csslpSupply', 'front': 'Software bill of materials (SBOM)', 'back': 'An SBOM is a formal, machine-readable inventory of the components and dependencies in a piece of software, including names, versions and suppliers. It lets owners find affected products quickly when a new vulnerability in a component is announced.', 'detail': 'An SBOM lists what is inside; it does not by itself tell whether the component is vulnerable or exploitable in your product.'},
    {'id': 'f118', 'cat': 'csslpSupply', 'front': 'SBOM formats: SPDX and CycloneDX', 'back': 'SPDX (from the Linux Foundation, also an ISO standard) and CycloneDX (from OWASP, now an Ecma standard) are the two main machine-readable SBOM formats. The NTIA minimum elements, such as supplier, component name, version and dependency relationships, apply to either.', 'detail': 'Know both names and that either is acceptable; the exam asks for the purpose of an SBOM more than the syntax.'},
    {'id': 'f119', 'cat': 'csslpSupply', 'front': 'Software composition analysis (SCA)', 'back': 'SCA tools identify open-source and third-party components in a codebase, report their known vulnerabilities and licenses, and can generate an SBOM. Running SCA in the pipeline detects newly disclosed flaws in components already shipped.', 'detail': 'SAST looks at the code you wrote; SCA looks at the code you imported.'},
    {'id': 'f120', 'cat': 'csslpSupply', 'front': 'Vulnerability Exploitability eXchange (VEX)', 'back': 'A VEX statement is a supplier assertion about whether a known vulnerability in a component actually affects a product, for example not affected because the vulnerable function is never called. It lets customers filter SBOM-based alerts.', 'detail': 'VEX reduces noise from vulnerabilities that exist in a component but are not exploitable in the product.'},
    {'id': 'f121', 'cat': 'csslpSupply', 'front': 'Dependency confusion and typosquatting', 'back': 'In dependency confusion an attacker publishes a public package with the same name as an organization internal package, at a higher version, so the build tool fetches the attacker version. Typosquatting uses names that resemble popular packages and relies on typing mistakes.', 'detail': 'Defenses include scoped or reserved internal names, private registries with controlled resolution, pinned versions and lock files, and checking hashes.'},
    {'id': 'f122', 'cat': 'csslpSupply', 'front': 'Supply-chain Levels for Software Artifacts (SLSA)', 'back': 'SLSA is a framework of incrementally stronger requirements for build integrity and provenance, so consumers can verify where and how an artifact was built. Higher levels require a hosted, tamper-resistant build with signed provenance.', 'detail': 'Provenance is a verifiable record of the source, build process and builder that produced an artifact.'},
    {'id': 'f123', 'cat': 'csslpSupply', 'front': 'Open-source license types: permissive versus copyleft', 'back': 'Permissive licenses such as MIT, BSD and Apache 2.0 allow broad reuse with few conditions, while copyleft licenses such as GPL require derivative works to be distributed under the same terms. AGPL extends this to software offered over a network.', 'detail': 'License compliance is a legal risk found through SCA; mixing a copyleft component into proprietary software can force source disclosure.'},
    {'id': 'f124', 'cat': 'csslpSupply', 'front': 'Third-party and supplier risk assessment', 'back': 'Before adopting a supplier or component, assess its security practices, vulnerability history, maintenance activity, certifications and reports such as SOC 2, and rate the risk against the importance of the function. Continue monitoring after selection, not only before.', 'detail': 'Selection is not the end; monitoring for new vulnerabilities, ownership changes and end of support continues for the whole life of the dependency.'},
    {'id': 'f125', 'cat': 'csslpSupply', 'front': 'Contractual security controls with suppliers', 'back': 'Contracts and service level agreements can require security standards, breach notification, the right to audit, secure development practices, vulnerability handling timelines and exit provisions. These are the enforceable part of third-party risk management.', 'detail': 'A questionnaire is evidence, but a contract term is what lets you act when the supplier falls short.'},
    {'id': 'f126', 'cat': 'csslpSupply', 'front': 'Software escrow', 'back': 'Software escrow places a copy of source code, build instructions and related materials with a neutral third party, to be released to the customer if the vendor fails, goes out of business or stops support. It protects continuity for critical custom or proprietary software.', 'detail': 'Escrow is only useful if the deposit is complete and verified as buildable; an untested deposit gives false assurance.'},
    {'id': 'f127', 'cat': 'csslpSupply', 'front': 'Common Criteria (ISO/IEC 15408) and evaluation assurance levels', 'back': 'Common Criteria is an international standard for evaluating the security of products against a Security Target, optionally conforming to a Protection Profile, and results are given as an evaluation assurance level from EAL1 to EAL7. A higher level means more rigorous evaluation, not necessarily more security features.', 'detail': 'EAL measures confidence in the evaluation, with EAL4 (methodically designed, tested and reviewed) being a common commercial level; EAL7 is formally verified design and testing.'},
    {'id': 'f128', 'cat': 'csslpSupply', 'front': 'Reproducible builds and artifact provenance', 'back': 'A reproducible build produces bit-for-bit identical output from the same source, so independent parties can verify that a released binary matches the published source. Signed provenance and artifact signing, such as with Sigstore, let consumers check integrity and origin.', 'detail': 'This is the control that detects tampering inside the build step, which a signature alone cannot, since a compromised builder can sign malicious output.'},
]

QUESTIONS = [
    {'id': 'q1', 'cat': 'csslpConcepts', 'type': 'mc', 'question': 'A payment API checks the caller token when a session starts but trusts the same session for every later request, even after an administrator revokes the user permissions. Which design principle is being violated?', 'options': ['Complete mediation, because every access must be checked each time it occurs', 'Separation of duties, because one user is performing the whole operation', 'Economy of mechanism, because the token check has too many steps', 'Open design, because the revocation logic is not publicly documented'], 'correct': 0, 'explanation': 'Complete mediation requires that every access to every object be authorized at the time of the access, so a revoked permission takes effect immediately. A one-time check followed by cached trust breaks that. Separation of duties is about splitting a sensitive process among people, open design is about not relying on secrecy of the design, and economy of mechanism is about keeping mechanisms simple, none of which describes cached authorization.'},
    {'id': 'q2', 'cat': 'csslpConcepts', 'type': 'mc', 'question': 'A microservice that reads product images runs under a database administrator account because that was the quickest way to get it working. Which principle most directly calls for changing this?', 'options': ['Defense in depth, by adding a second administrator account as a backup', 'Psychological acceptability, by making the account easier to remember', 'Least privilege, giving the service only the access it needs', 'Separation of privilege, by requiring two administrators to approve each query'], 'correct': 2, 'explanation': 'Least privilege says each component should hold only the permissions required for its job, which here is read access to one data set. An administrator account lets any bug in the service become a full database compromise. Adding another administrator account, easier credentials or approvals per query do not reduce the excess privilege itself.'},
    {'id': 'q3', 'cat': 'csslpConcepts', 'type': 'mc', 'question': 'After a failed deployment, a gateway starts allowing all traffic through because its policy file could not be loaded. Which principle was ignored?', 'options': ['Least common mechanism: policy files should never be shared between components', 'Open design: the format of the policy file must be published publicly', 'Accountability: every failed deployment must generate a signed audit record', 'Fail-safe defaults: access should be denied when the system fails or errors'], 'correct': 3, 'explanation': 'Fail-safe defaults means that when something goes wrong, the system should end up in a secure state, normally denying access, and permission should be explicitly granted. A gateway that opens up when its policy fails does the reverse. Least common mechanism, open design and accountability are real principles but do not address the failure behavior in this scenario.'},
    {'id': 'q4', 'cat': 'csslpConcepts', 'type': 'mc', 'question': 'A team keeps its encryption algorithm secret and treats that as its main protection. A reviewer objects. What is the best basis for the objection?', 'options': ['Security should rest on protecting keys, so a public, peer-reviewed algorithm is preferred', 'Secret algorithms are prohibited by nearly all data protection regulations in force today', 'Only symmetric algorithms can be kept hidden without any loss of message integrity', 'Algorithms that are kept secret always execute more slowly than published algorithms do'], 'correct': 0, 'explanation': 'The open design principle, which comes from Kerckhoffs, holds that a system should stay secure even if everything except the key is public, because secrets about design eventually leak and unreviewed algorithms often hide weaknesses. The other statements are not true: secrecy is generally legal, speed is unrelated, and symmetry has no bearing.'},
    {'id': 'q5', 'cat': 'csslpConcepts', 'type': 'mc', 'question': 'A web form needs a security control against automated account takeover but users are already abandoning it because the rules are complicated. Which principle supports the best recommendation?', 'options': ['Psychological acceptability: a protective control that people can use correctly', 'Economy of mechanism: remove the control entirely to cut down the complexity', 'Fail-safe defaults: block every login until the user proves identity in person', 'Defense in depth: require each user to pass every possible control available'], 'correct': 0, 'explanation': 'Controls that are too hard to use get bypassed or abandoned, so the design should achieve the security goal in a usable way, for example with multi-factor authentication that fits normal workflow. Removing the control gives up the protection, blocking all logins breaks the service, and stacking every control makes usability worse.'},
    {'id': 'q6', 'cat': 'csslpConcepts', 'type': 'mc', 'question': 'An application stores a customer record worth about 40,000 dollars. An analyst estimates a successful attack would expose 25 percent of its value and happens twice every ten years. What is the annualized loss expectancy?', 'options': ['10,000 dollars', '20,000 dollars', '2,000 dollars', '8,000 dollars'], 'correct': 2, 'explanation': 'Single loss expectancy is 40,000 times 25 percent, which is 10,000 dollars. The annualized rate of occurrence is twice in ten years, or 0.2 per year. Multiplying gives 2,000 dollars per year. A countermeasure costing more than that annually would not be justified on this risk alone.'},
    {'id': 'q7', 'cat': 'csslpConcepts', 'type': 'mc', 'question': 'The product owner decides not to fix a moderate vulnerability in a legacy report module this quarter after reading the risk summary and signing a record of the decision. Which risk treatment is this?', 'options': ['Risk acceptance, a knowing decision by the accountable owner', 'Risk avoidance, because the risk is no longer discussed', 'Risk mitigation, because the owner reviewed the vulnerability', 'Risk transference, because responsibility moved to the product owner'], 'correct': 0, 'explanation': 'Acceptance means the accountable owner, informed of the risk, chooses to tolerate it, and it should be documented and revisited. Transference shifts financial impact to another party such as an insurer, avoidance eliminates the risky activity, and mitigation reduces the likelihood or impact with a control. Reviewing the issue is not itself mitigation.'},
    {'id': 'q8', 'cat': 'csslpConcepts', 'type': 'mc', 'question': 'Management wants a feature that would collect customers contact lists even though the product does not use them. Applying privacy by design, what should the architect recommend FIRST?', 'options': ['Do not collect the contact lists unless a documented purpose requires them', 'Collect them and arrange for staff to delete them manually after one year', 'Collect them and encrypt the stored copy with a strong, current algorithm', 'Collect them and display a detailed privacy notice on the sign-up screen'], 'correct': 0, 'explanation': 'Privacy by design starts with data minimization: data that is never collected cannot leak or be misused, and each collected item needs a defined purpose. Encryption, notices and manual deletion are all weaker than not collecting unnecessary data in the first place.'},
    {'id': 'q9', 'cat': 'csslpConcepts', 'type': 'mc', 'question': 'A vendor ships a product with administrator remote access enabled and a default password, and relies on a hardening guide to tell customers to change it. Which concept does this contradict?', 'options': ['Risk transference: the customer now owns all of the product risk', 'Secure by default: the product should ship already hardened', 'Non-repudiation: actions on the product cannot be tied to a specific person', 'Accountability: the vendor failed to publish the product access logs'], 'correct': 1, 'explanation': 'Secure by default means the out-of-the-box configuration is already safe, so customers do not need extra steps to get protection. Shipping an insecure default and documenting the fix moves the burden to the customer. Non-repudiation and accountability are about tracing actions, and transference is a risk treatment, none of which fits.'},
    {'id': 'q10', 'cat': 'csslpConcepts', 'type': 'mc', 'question': 'A threat is described as an attacker with stolen credentials, and a weakness is described as the absence of multi-factor authentication. What is the risk?', 'options': ['The stolen credentials themselves, since they are the asset that has been exposed here', 'The absence of multi-factor authentication, since it is the only item the team controls', 'The identity of the attacker, since risk is defined by who is carrying out the attack', 'The chance and impact of the attacker using the credentials against the gap'], 'correct': 3, 'explanation': 'Risk is the combination of the likelihood that a threat exploits a vulnerability and the resulting impact. The threat is the attacker, the vulnerability is the missing control, and the credentials are an asset or an attack input. Treating any single element as the risk skips the likelihood and impact analysis.'},
    {'id': 'q11', 'cat': 'csslpLifecycle', 'type': 'mc', 'question': 'A company wants to compare its software security program with others in the same industry by looking at the activities those organizations actually perform. Which model fits BEST?', 'options': ['BSIMM, because it describes what real programs are observed doing', 'CMMI, because it measures only hardware manufacturing quality', 'SAMM, because it prescribes the target activities for every organization', 'The Microsoft SDL, because it was written for Windows products only'], 'correct': 0, 'explanation': 'BSIMM is a descriptive measurement of what many organizations actually do, which makes benchmarking against peers possible. SAMM and the SDL are prescriptive, telling you what to do rather than reporting what peers do. CMMI is a general process maturity model, not tied to hardware manufacturing, and the SDL is not limited to Windows.'},
    {'id': 'q12', 'cat': 'csslpLifecycle', 'type': 'mc', 'question': 'A security lead wants a roadmap with measurable maturity levels across governance, design, implementation, verification and operations, tailored to the company risk. Which framework is the BEST fit?', 'options': ['STRIDE, which classifies threats against the elements of a system design', 'Common Criteria, which assigns evaluation assurance levels to evaluated products', 'OWASP SAMM, which defines five business functions with three maturity levels', 'NIST SP 800-61, which defines the phases of incident handling and recovery'], 'correct': 2, 'explanation': 'SAMM is organized into five business functions (governance, design, implementation, verification, operations), each with security practices and maturity levels, designed for building an improvement roadmap. SP 800-61 is incident response, Common Criteria evaluates products, and STRIDE is a threat classification model.'},
    {'id': 'q13', 'cat': 'csslpLifecycle', 'type': 'mc', 'question': 'A federal customer asks a software supplier to attest that it follows secure development practices. The practices are grouped as prepare the organization, protect the software, produce well-secured software and respond to vulnerabilities. Which document is the customer referencing?', 'options': ['The OWASP Application Security Verification Standard, level 2', 'The NIST Secure Software Development Framework, SP 800-218', 'The BSIMM report for the supplier industry sector', 'NIST SP 800-53, the catalog of security and privacy controls'], 'correct': 1, 'explanation': 'The SSDF organizes practices into exactly those four groups and is the basis of US federal secure software attestations. ASVS lists verification requirements for applications, BSIMM is a descriptive study, and SP 800-53 is a control catalog for systems rather than a development practice framework.'},
    {'id': 'q14', 'cat': 'csslpLifecycle', 'type': 'mc', 'question': 'A team is moving from quarterly releases to deploying several times a day. Which approach to security activities is BEST?', 'options': ['Automate checks in the pipeline and add security criteria to every story', 'Keep a single manual security review before the annual external audit', 'Freeze deployments until every developer completes a security certification', 'Move all security testing to a separate team that works after release'], 'correct': 0, 'explanation': 'Frequent delivery needs security that scales with it: automated static analysis, dependency checks and policy gates in the pipeline plus testable acceptance criteria in each story. Periodic reviews and post-release testing cannot keep pace, and a blanket freeze would stop delivery without fixing the process.'},
    {'id': 'q15', 'cat': 'csslpLifecycle', 'type': 'mc', 'question': 'A project manager asks what a security champions program contributes to the lifecycle. What is the BEST answer?', 'options': ['A mandatory audit role that is independent of each development team', 'A group that holds the authority to approve or block every release', 'Embedded developers who promote secure practice and act as local contacts', 'A replacement for the central security team in smaller organizations'], 'correct': 2, 'explanation': 'Champions extend security knowledge and early detection into each team and give the security team a scaled network of contacts. They are not an approval authority, they do not replace specialists, and they are embedded rather than independent auditors.'},
    {'id': 'q16', 'cat': 'csslpLifecycle', 'type': 'mc', 'question': 'Which security metric BEST shows whether the vulnerability handling process is improving over time?', 'options': ['The total number of vulnerabilities that one scanner reported this month', 'The count of lines of code scanned by static analysis each week', 'The number of developers who finished the annual training video', 'The trend in mean time to remediate vulnerabilities, by severity'], 'correct': 3, 'explanation': 'A trend in time to remediate by severity shows how effectively the organization responds to findings. A raw count can rise because testing improved, training completion measures activity rather than outcome, and lines scanned says nothing about whether findings are fixed.'},
    {'id': 'q17', 'cat': 'csslpLifecycle', 'type': 'mc', 'question': 'A high-severity change to a payment module must go live tonight to stop active fraud. What is the BEST way to handle change management?', 'options': ['Wait for the next scheduled change board meeting in two weeks time', 'Let the developer who wrote the fix deploy it without keeping any record', 'Bypass change management completely because the fix is so urgent', 'Use the emergency change path with delegated approval and review it later'], 'correct': 3, 'explanation': 'Mature change management has an expedited path for emergencies that keeps accountability: delegated approval, a record and a retrospective review. Skipping the process leaves no control, waiting two weeks ignores the urgency, and an unrecorded single-person change breaks separation of duties.'},
    {'id': 'q18', 'cat': 'csslpLifecycle', 'type': 'mc', 'question': 'A document says all production systems must use approved encryption. Another says AES-256 must be used for data at rest in the customer database. A third suggests developers consider hardware modules where practical. Which are correctly labeled in order?', 'options': ['Procedure, standard, policy', 'Guideline, policy, standard', 'Standard, guideline, policy', 'Policy, standard, guideline'], 'correct': 3, 'explanation': 'A policy is a high-level mandatory statement of intent, a standard is a mandatory and specific requirement such as a particular algorithm, and a guideline is optional recommended advice. A procedure would be the step-by-step instructions, which none of the three statements is.'},
    {'id': 'q19', 'cat': 'csslpReq', 'type': 'mc', 'question': 'A requirements document lists detailed features but says nothing about authentication, logging or data protection. What should the secure software professional do FIRST?', 'options': ['Wait for penetration testing to show which controls turn out to be missing', 'Copy the control list from another team without checking whether it applies', 'Record the missing controls as defects to be fixed during integration testing', 'Elicit security requirements from data classes, laws and abuse cases'], 'correct': 3, 'explanation': 'Security requirements must be defined early so they can be designed, built and tested, and they come from the data classification, applicable regulations, risk and abuse cases. Waiting for testing or treating them as defects makes fixes costly, and copying controls without analysis may miss real needs or add unneeded ones.'},
    {'id': 'q20', 'cat': 'csslpReq', 'type': 'mc', 'question': 'Which artifact BEST shows that each security requirement has been designed, implemented and tested?', 'options': ['A ranked list of the penetration test findings, sorted by severity and component', 'A security requirements traceability matrix linking requirements to design and tests', 'A copy of the organization information security policy approved by management', 'A diagram of the production network topology showing every firewall and subnet'], 'correct': 1, 'explanation': 'A traceability matrix maps each requirement to the design elements, implementation and test cases that satisfy it, exposing gaps in coverage. Findings, policy copies and network diagrams do not tie each requirement to its verification.'},
    {'id': 'q21', 'cat': 'csslpReq', 'type': 'mc', 'question': 'A designer wants to find security requirements by thinking like an attacker who abuses the checkout feature. Which technique does this describe?', 'options': ['Creating a business impact analysis', 'Writing abuse or misuse cases', 'Calculating the annualized loss expectancy', 'Writing use cases for the intended user flows'], 'correct': 1, 'explanation': 'Abuse and misuse cases describe how an attacker or careless user could subvert a feature and give rise to requirements such as rate limits, validation and lockout. Use cases cover intended behavior, ALE is a quantitative risk figure, and a business impact analysis identifies critical functions and recovery needs.'},
    {'id': 'q22', 'cat': 'csslpReq', 'type': 'mc', 'question': 'A hospital application stores diagnoses, billing addresses and appointment times. The architect needs a basis for deciding the encryption, access control and retention rules for each field. What should be done FIRST?', 'options': ['Classify the data by sensitivity and regulatory scope together with the data owner', 'Ask the developers to decide which fields happen to be easiest to protect', 'Select the strongest available encryption algorithm and apply it to every field', 'Move all of the data to the cloud provider default storage tier immediately'], 'correct': 0, 'explanation': 'Classification by the data owner determines sensitivity and applicable rules, which then drive control choices. Applying the strongest encryption everywhere ignores context and cost, a default storage tier does not address requirements, and convenience is not a basis for protection.'},
    {'id': 'q23', 'cat': 'csslpReq', 'type': 'mc', 'question': 'A product will process personal data of people in the European Union for a new purpose. Which activity should happen during requirements, before design is finalized?', 'options': ['A data protection impact assessment of risks to the individuals concerned', 'A load test that confirms response time targets are met under peak demand', 'A disaster recovery drill performed at the secondary site over a weekend', 'A code review focused on the layout and styling of the user interface'], 'correct': 0, 'explanation': 'A data protection impact assessment is required under GDPR for high-risk processing and should shape requirements and design before data is collected. Load tests, interface reviews and recovery drills are valuable, but they do not assess privacy risk to individuals.'},
    {'id': 'q24', 'cat': 'csslpReq', 'type': 'mc', 'question': 'A sprint story states that the system must be secure. How can the team make this testable?', 'options': ['Split it into two smaller stories without defining any further criteria', 'Move it to the project risk register where it will be recorded as an assumption', 'Replace it with measurable criteria, such as server-side validation of all inputs', 'Leave it as written and rely on the testers to judge whether it is satisfied'], 'correct': 2, 'explanation': 'A requirement can only be verified if it has specific, observable criteria, so security stories need concrete acceptance conditions that become test cases. Judgement-based testing, burying it in a register and splitting it without criteria all leave it unverifiable.'},
    {'id': 'q25', 'cat': 'csslpReq', 'type': 'mc', 'question': 'The business states that after an outage it can tolerate no more than 15 minutes of lost transactions and must be running within two hours. How should this be recorded?', 'options': ['An RPO of 15 minutes and an RTO of two hours', 'An RTO of 15 minutes and an RPO of two hours', 'A generic availability figure of 99 percent without any time values', 'An ALE of 15 minutes and an SLE of two hours'], 'correct': 0, 'explanation': 'Recovery point objective is the maximum tolerable data loss measured in time, here 15 minutes, and recovery time objective is the maximum time to restore service, here two hours. Reversing them is a frequent error. ALE and SLE are loss figures in money, and a generic percentage does not capture these targets.'},
    {'id': 'q26', 'cat': 'csslpReq', 'type': 'mc', 'question': 'A system holds low-impact public data, but a failure in its integrity could cause loss of life in a connected process. How does FIPS 199 categorize the overall system?', 'options': ['Moderate, because the category is the average of the three impact ratings', 'Undetermined, because categorization must wait for a penetration test to finish', 'Low, because the data is public and confidentiality is the main property here', 'High, because the highest impact among the three properties sets the category'], 'correct': 3, 'explanation': 'FIPS 199 uses the high-water mark, so a single high-impact property raises the system to high. Averaging or choosing only confidentiality understates the risk, and categorization is a design-time analysis that does not wait for testing.'},
    {'id': 'q27', 'cat': 'csslpReq', 'type': 'mc', 'question': 'An organization wants to verify web application security requirements at different assurance levels depending on risk, from basic to highly sensitive. Which resource is the BEST source?', 'options': ['The OWASP Top 10, which is a ranked awareness list of web application risks', 'The SPDX standard, which describes formats for software component inventories', 'The OWASP Application Security Verification Standard, which defines three levels', 'The CVSS specification, which scores the severity of individual vulnerabilities'], 'correct': 2, 'explanation': 'ASVS provides detailed testable requirements organized into three levels for different assurance needs. The Top 10 is for awareness and is not a verification standard, CVSS rates findings, and SPDX describes bill of materials formats.'},
    {'id': 'q28', 'cat': 'csslpReq', 'type': 'mc', 'question': 'Customer data is retained indefinitely in an application because nobody defined a retention period. What is the MAIN risk this creates?', 'options': ['Higher licensing costs for the database engine that holds the records', 'Reduced mathematical accuracy of the encryption algorithm in use', 'Larger breach impact, and possible violation of laws that limit retention', 'A noticeably longer response time for the application login function'], 'correct': 2, 'explanation': 'Keeping personal data longer than needed enlarges what an attacker can steal and can breach laws requiring deletion once the purpose ends. Licensing cost, encryption accuracy and login speed are not the main security concern.'},
    {'id': 'q29', 'cat': 'csslpDesign', 'type': 'mc', 'question': 'A team is asked to find what could go wrong in a new design, classifying threats as spoofing, tampering, repudiation, information disclosure, denial of service and elevation of privilege. Which method is it using?', 'options': ['STRIDE', 'CVSS', 'DREAD', 'PASTA'], 'correct': 0, 'explanation': 'STRIDE is the threat classification scheme named by those six categories. DREAD scores severity, PASTA is a seven-stage risk-centric process, and CVSS scores the severity of known vulnerabilities, so none of those is a classification of threat types.'},
    {'id': 'q30', 'cat': 'csslpDesign', 'type': 'mc', 'question': 'After threats are identified, the team needs to rank them by damage potential, reproducibility, exploitability, affected users and discoverability. Which technique applies?', 'options': ['STRIDE', 'DREAD', 'An attack tree', 'LINDDUN'], 'correct': 1, 'explanation': 'DREAD rates threats using those five factors so the team can prioritize. STRIDE categorizes rather than ranks, LINDDUN is a privacy-focused threat method, and an attack tree models paths to an attacker goal.'},
    {'id': 'q31', 'cat': 'csslpDesign', 'type': 'mc', 'question': 'An architect wants a threat modeling approach that begins with business objectives, defines technical scope, simulates attacks and ends with risk and countermeasure analysis. Which should be chosen?', 'options': ['Trike, which excludes any attacker perspective', 'STRIDE, which analyzes each diagram element for six threat types', 'DREAD, which provides a scoring formula only', 'PASTA, a seven-stage risk-centric method'], 'correct': 3, 'explanation': 'PASTA is risk-centric and attack-simulation based, linking technical threats to business impact through seven stages. STRIDE and DREAD are narrower, and Trike is a risk-based approach that does model threats against assets, so the claim that it excludes attackers is wrong.'},
    {'id': 'q32', 'cat': 'csslpDesign', 'type': 'mc', 'question': 'During threat modeling on a data flow diagram, where should the team concentrate FIRST?', 'options': ['On flows that cross trust boundaries, because data changes trust level there', 'On the user interface colors and layout, because users see them first', 'On the oldest components, because age alone indicates exposure', 'On flows entirely inside a single process, because they are the most numerous'], 'correct': 0, 'explanation': 'Threats cluster where data passes between zones with different trust or privilege, such as from the internet into the application or from the application into the database. Internal flows, interface appearance and age are less reliable indicators of exposure.'},
    {'id': 'q33', 'cat': 'csslpDesign', 'type': 'mc', 'question': 'A company uses a VPN so that any device on the internal network can reach the HR system without further checks. Which change best aligns with zero trust?', 'options': ['Add a second perimeter firewall in front of the existing first one', 'Authenticate and authorize every request using identity, device and context', 'Hide the HR system address from the internal DNS records', 'Extend the VPN so that contractors and partners can use it as well'], 'correct': 1, 'explanation': 'Zero trust removes implicit trust from network location and evaluates every request against identity, device state and policy. Another firewall and a wider VPN keep the perimeter model, and hiding a DNS record is obscurity rather than an access decision.'},
    {'id': 'q34', 'cat': 'csslpDesign', 'type': 'mc', 'question': 'A microservices system authenticates users at the API gateway, and internal services trust any call that reaches them. What is the MOST significant weakness?', 'options': ['Anyone inside the network can call any service without being checked', 'Logs cannot be correlated across the different services at all', 'Individual services will not be able to scale horizontally under load', 'The gateway cannot terminate TLS connections coming from external users'], 'correct': 0, 'explanation': 'If internal services trust all callers, a single compromised component or network foothold gives access to every service. Design should authenticate service identities (for example with mutual TLS) and authorize in each service. The other issues are unrelated to the trust model.'},
    {'id': 'q35', 'cat': 'csslpDesign', 'type': 'mc', 'question': 'An API endpoint returns an order when called with an order identifier. A tester changes the identifier to another customer order number and receives that order. Which API design flaw is this?', 'options': ['Excessive rate limiting, which ended up exposing the order data', 'Broken object level authorization, as object ownership was never checked', 'Broken authentication, since the tester had no account at all', 'Insufficient logging, which causes the identifiers to be exposed'], 'correct': 1, 'explanation': 'The caller is authenticated but the API does not verify the caller is allowed to access that specific object, which is object level authorization. Rate limiting does not expose data, the tester did have valid credentials in this scenario, and logging does not cause the data exposure.'},
    {'id': 'q36', 'cat': 'csslpDesign', 'type': 'mc', 'question': 'A company moves a workload to a platform as a service offering. Which responsibility remains with the customer?', 'options': ['Providing physical access control for the provider datacenters', 'Securing its own code, data, identities and configuration', 'Patching the underlying hypervisor and the physical hosts', 'Maintaining redundancy of the provider network backbone'], 'correct': 1, 'explanation': 'In the shared responsibility model the provider manages the infrastructure and platform layers, while the customer is always responsible for their data, identities, access configuration and the code they deploy. Hypervisor patching, physical security and the backbone are provider responsibilities.'},
    {'id': 'q37', 'cat': 'csslpDesign', 'type': 'mc', 'question': 'A team builds a container image for a customer-facing service. Which design choice BEST reduces risk?', 'options': ['An image with credentials baked in so deployment needs no further configuration', 'A full operating system image that includes the debugging tools for convenience', 'An image that runs as root so that file permissions are simpler to manage', 'A minimal scanned image run as non-root, with secrets injected at runtime'], 'correct': 3, 'explanation': 'Smaller images have fewer components to be vulnerable, scanning finds known flaws, non-root limits what a compromise can do, and runtime secrets keep credentials out of the image. Extra tools, root and embedded credentials each enlarge the attack surface or leak secrets.'},
    {'id': 'q38', 'cat': 'csslpDesign', 'type': 'mc', 'question': 'A designer wants single sign-on across several applications and needs a protocol that carries the identity of the authenticated user on top of OAuth 2.0. Which is correct?', 'options': ['OpenID Connect', 'Kerberos with a shared service account', 'Basic authentication over HTTPS', 'The OAuth 2.0 authorization code flow alone'], 'correct': 0, 'explanation': 'OpenID Connect adds an identity layer, with an ID token about the authenticated user, over OAuth 2.0. OAuth 2.0 alone is for delegated authorization, not authentication, Kerberos with a shared account does not provide federated identity of this kind, and Basic authentication sends credentials with every request.'},
    {'id': 'q39', 'cat': 'csslpDesign', 'type': 'mc', 'question': 'A design review finds that sensitive keys will be stored in the same database as the encrypted data they protect. What is the BEST recommendation?', 'options': ['Hold keys in a separate key service or hardware module with its own controls', 'Keep the keys where they are but raise the database backup frequency', 'Rename the key column so the keys are harder for an attacker to find', 'Encrypt the key using the same key to double the protection it provides'], 'correct': 0, 'explanation': 'Separating key management from the data means an attacker who gets the data does not automatically get the means to decrypt it, and key services provide rotation, access control and audit. Renaming is obscurity, self-encryption is circular, and more backups would spread the keys further.'},
    {'id': 'q40', 'cat': 'csslpImpl', 'type': 'mc', 'question': 'A search page builds its database query by concatenating the search text into the SQL statement. Which fix is the MOST effective?', 'options': ['Strip single quotes out of the input before it is concatenated', 'Show a generic message whenever the database query fails', 'Use parameterized queries so that input is always treated as data', 'Hide the search page behind a very long and unpredictable URL'], 'correct': 2, 'explanation': 'Parameterization separates code and data so the database never interprets input as SQL syntax, which solves the problem at its root. Stripping quotes is a fragile block-list, an obscure URL provides no protection, and hiding errors does not stop injection.'},
    {'id': 'q41', 'cat': 'csslpImpl', 'type': 'mc', 'question': 'A comment field echoes user input inside an HTML page, and a tester inserts script that runs in other users browsers. Which control is the PRIMARY defense?', 'options': ['Encrypting the database column that stores the comments', 'Context-aware output encoding when the data is rendered', 'Requiring all users to change their passwords more often', 'Raising the maximum length allowed for the comment field'], 'correct': 1, 'explanation': 'Cross-site scripting is prevented chiefly by encoding output for its context so the browser treats it as text, with input validation and a content security policy as additional layers. Encryption at rest, a longer field and password rotation do not stop script execution in the browser.'},
    {'id': 'q42', 'cat': 'csslpImpl', 'type': 'mc', 'question': 'A banking site relies on session cookies. An attacker lures a logged-in user to a page that silently submits a transfer request to the bank. Which defense directly addresses this?', 'options': ['Hashing the session identifier in the database', 'Limiting the number of failed logins', 'Output encoding of the account number', 'Anti-forgery tokens plus SameSite cookies'], 'correct': 3, 'explanation': 'Cross-site request forgery depends on the browser automatically attaching cookies, so a per-request unpredictable token and SameSite cookies defeat it. Output encoding is for script injection, hashing session identifiers protects them in storage, and login throttling targets guessing attacks.'},
    {'id': 'q43', 'cat': 'csslpImpl', 'type': 'mc', 'question': 'A developer must store user passwords. Which approach is BEST?', 'options': ['Hash each password with a unique salt using Argon2id or bcrypt', 'Store the passwords in plain text inside a well access-controlled database', 'Encrypt the passwords with AES so that they can be recovered when forgotten', 'Hash every password with plain SHA-256 and without any salt'], 'correct': 0, 'explanation': 'Passwords never need to be recovered, so they should be hashed with a unique salt and a deliberately slow, memory-hard algorithm to make offline guessing expensive. Reversible encryption exposes all passwords if the key is taken, unsalted fast hashes are cracked quickly with tables and GPUs, and plain text is unacceptable.'},
    {'id': 'q44', 'cat': 'csslpImpl', 'type': 'mc', 'question': 'A scan of the repository history shows a cloud access key committed six months ago and removed the next day. What should be done?', 'options': ['Add a comment to the code warning developers never to commit any keys', 'Rewrite the repository history and carry on using the same key', 'Do nothing, since the key was removed from the current version of the code', 'Revoke and rotate the key, and adopt a secrets manager with scanning'], 'correct': 3, 'explanation': 'Anything committed to version control may have been copied or cached, so the secret must be revoked and replaced regardless of deletion. A secrets manager and automated secret scanning address the root cause. Removing it from the current version or merely rewriting history cannot undo any copies, and a comment is not a control.'},
    {'id': 'q45', 'cat': 'csslpImpl', 'type': 'mc', 'question': 'A C program copies user input into a 64-byte array with an unchecked function. Which long-term action BEST reduces this class of vulnerability?', 'options': ['Use bounds checking and move the component to a memory-safe language', 'Enable verbose error messages so that overflows are easier to diagnose', 'Rely only on address space layout randomization to stop exploitation', 'Run the program only during off-peak hours when traffic is low'], 'correct': 0, 'explanation': 'Bounds checking removes the bug, and memory-safe languages eliminate whole classes of memory errors. Randomization is a mitigation that raises the difficulty of exploitation without fixing the flaw, verbose errors leak information, and timing has no effect on exploitability.'},
    {'id': 'q46', 'cat': 'csslpImpl', 'type': 'mc', 'question': 'An application checks that a file is writable by the user and then, in a separate step, opens it for writing. An attacker swaps the file for a link to a system file between the two steps. What flaw is this?', 'options': ['A cross-site request forgery weakness', 'An insecure direct object reference in the URL', 'A buffer over-read in the file system driver', 'A time-of-check to time-of-use race condition'], 'correct': 3, 'explanation': 'The state checked is not the state used because it changed between the check and the use, which is the definition of TOCTOU. Fixing it means performing the check and use atomically on the same handle. The other options describe different weakness categories.'},
    {'id': 'q47', 'cat': 'csslpImpl', 'type': 'mc', 'question': 'A web application shows users a full stack trace and the database query when an error occurs. What is the BEST remediation?', 'options': ['Remove logging from the application so that no details exist anywhere', 'Show the stack trace only to users who have logged in to the application', 'Encode the stack trace so that it is harder for a casual visitor to read', 'Show users a generic message and keep the details in protected logs'], 'correct': 3, 'explanation': 'Detailed errors reveal internals useful to attackers, while developers still need diagnostics, so keep them in protected logs and give users a generic message. Showing traces to logged-in users still leaks to any account holder, encoding does not help, and removing logs destroys accountability.'},
    {'id': 'q48', 'cat': 'csslpImpl', 'type': 'mc', 'question': 'A reviewer wants to find authorization logic flaws and design mistakes in a new module, not only pattern-based bugs. Which review approach is BEST?', 'options': ['A spelling and style check of the comments and identifiers in the source code', 'A static analysis scan run with the default rule set and no further review', 'A vulnerability scan of the production network performed by the operations team', 'Manual secure review by an experienced reviewer, complemented by automated tools'], 'correct': 3, 'explanation': 'Business logic and authorization flaws need human understanding of intent, and tools add breadth for known patterns, so a combination is strongest. A default scan misses logic flaws, a network vulnerability scan does not examine code logic, and comments are not security relevant.'},
    {'id': 'q49', 'cat': 'csslpImpl', 'type': 'mc', 'question': 'A team wants to ensure no single compromised developer account can push malicious code to the main branch. Which control is MOST effective?', 'options': ['A single shared team account that all of the developers log in with', 'Branch protection requiring an independent approved review, with signed commits', 'A weekly email asking developers to confirm that their commits are legitimate', 'Disabling the audit log in order to save repository storage space'], 'correct': 1, 'explanation': 'Requiring independent review enforces separation of duties so one account cannot merge alone, and signed commits tie changes to identities. Shared accounts destroy accountability, an email confirmation is not an enforcement, and removing logs weakens detection.'},
    {'id': 'q50', 'cat': 'csslpImpl', 'type': 'mc', 'question': 'A server component fetches any URL supplied by the user and returns the content. An attacker supplies an internal cloud metadata address and receives credentials. Which weakness is this?', 'options': ['Cross-site scripting', 'SQL injection', 'Server-side request forgery', 'Session fixation'], 'correct': 2, 'explanation': 'The server is tricked into making a request to a destination chosen by the attacker, reaching internal resources. Defenses include allow-listing destinations and blocking internal ranges. XSS targets browsers, SQL injection targets databases, and session fixation concerns session identifiers.'},
    {'id': 'q51', 'cat': 'csslpTest', 'type': 'mc', 'question': 'A team has the full source code of a new service and wants to find flaws before it is deployed anywhere. Which testing type is the BEST starting point?', 'options': ['Static application security testing', 'A distributed denial of service simulation', 'Dynamic application security testing against production', 'A bug bounty program'], 'correct': 0, 'explanation': 'Static analysis examines code without running it, so it can start as soon as code exists and points to the exact location. Dynamic testing needs a running application, a bounty program is run on live systems, and a denial of service simulation tests resilience rather than code flaws.'},
    {'id': 'q52', 'cat': 'csslpTest', 'type': 'mc', 'question': 'A vendor delivered only a compiled web application running in a staging environment, with no source code. Which technique can find vulnerabilities?', 'options': ['A code review of the branching strategy', 'Dynamic application security testing from the outside', 'Static analysis of the source code', 'Software composition analysis of the source repository'], 'correct': 1, 'explanation': 'DAST interacts with a running application like an attacker and requires no source, which fits this case. Source-based techniques are not possible without the code or repository.'},
    {'id': 'q53', 'cat': 'csslpTest', 'type': 'mc', 'question': 'A team wants accurate findings with few false positives by observing code behavior from inside the application while functional tests run. Which technology fits?', 'options': ['A network port scanner pointed at the application servers', 'Interactive application security testing with an instrumented agent', 'A web application firewall configured in blocking mode', 'A source line counter run against the repository on each build'], 'correct': 1, 'explanation': 'IAST places sensors in the running application so findings are tied to actual code paths exercised by tests. A port scanner only sees network exposure, a firewall is a protective control rather than a test, and a line counter measures size.'},
    {'id': 'q54', 'cat': 'csslpTest', 'type': 'mc', 'question': 'A parser for a binary file format has crashed unpredictably in production after receiving unusual files. Which technique is MOST likely to find similar flaws before release?', 'options': ['Coverage-guided fuzz testing with malformed inputs', 'Reviewing the user interface for accessibility problems', 'Scanning every dependency for outdated version numbers', 'Checking that the code follows the team naming conventions'], 'correct': 0, 'explanation': 'Fuzzing generates large numbers of malformed inputs to provoke crashes and memory errors, and is especially effective on parsers. Dependency scanning, accessibility reviews and naming checks do not exercise the parser with hostile data.'},
    {'id': 'q55', 'cat': 'csslpTest', 'type': 'mc', 'question': 'A company hires an outside firm to attempt to break into its application. What must be in place BEFORE testing starts?', 'options': ['A promise from the testers to fix any vulnerabilities they find', 'Written authorization and agreed rules of engagement for the work', 'Disabling all the monitoring so testers can work unobserved', 'Production database credentials given to the testers in advance'], 'correct': 1, 'explanation': 'Written authorization and agreed rules protect both parties and prevent accidental damage or legal exposure by defining what is in scope. Testers do not fix flaws, disabling monitoring defeats part of what is being validated, and unneeded credentials are not a prerequisite.'},
    {'id': 'q56', 'cat': 'csslpTest', 'type': 'mc', 'question': 'A manager asks why the team runs both vulnerability scans and annual penetration tests. What is the BEST explanation?', 'options': ['Scans give frequent breadth over known weaknesses; pen tests show chained exploits', 'They are the same activity, repeated twice to satisfy the auditors', 'Scans exploit the weaknesses they find, while penetration tests only list them', 'Penetration tests replace scans whenever the testing budget is limited'], 'correct': 0, 'explanation': 'Automated scans are cheap and repeatable and find known issues, while penetration testing is a skilled attempt to exploit and combine flaws to demonstrate real impact. The roles in the other statements are reversed, identical or incorrectly substituted.'},
    {'id': 'q57', 'cat': 'csslpTest', 'type': 'mc', 'question': 'A company copies its production customer database into a test environment to make tests more realistic. What is the BEST control?', 'options': ['Leave it unchanged, because the test network is internal', 'Tell the testers not to look at the personal data fields', 'Encrypt the test database but keep the real values inside it', 'Use synthetic data, or mask and anonymize the data first'], 'correct': 3, 'explanation': 'Test environments typically have weaker controls, so real personal data must not be there unmasked. Synthetic or masked data keeps tests useful and reduces breach and compliance exposure. An internal network, verbal instructions or encryption alone do not remove the exposure.'},
    {'id': 'q58', 'cat': 'csslpTest', 'type': 'mc', 'question': 'A static scanner reports hundreds of findings, many of which turn out not to be real. What is the BEST response?', 'options': ['Fix every finding in order without first checking whether it is real', 'Disable the tool because false positives make its results worthless', 'Mark every finding as accepted risk to clear the backlog quickly', 'Tune the rules and triage by risk instead of ignoring the tool'], 'correct': 3, 'explanation': 'False positives are normal and are managed by tuning and triage; ignoring the tool risks false negatives from real flaws that get missed. Blanket acceptance without assessment is not a legitimate risk decision, and fixing all findings blindly wastes effort.'},
    {'id': 'q59', 'cat': 'csslpTest', 'type': 'mc', 'question': 'A critical vulnerability was fixed last quarter and appears again after a refactor. What practice would MOST directly prevent that?', 'options': ['Train developers on the organization password policy', 'Raise code coverage targets for modules unrelated to the fix', 'Move the application to a different hosting region', 'Add an automated regression test for that exact vulnerability'], 'correct': 3, 'explanation': 'A regression test that exercises the exact flaw fails the build if it returns. Coverage numbers on unrelated code, password training and moving regions do not guard against reintroducing that defect.'},
    {'id': 'q60', 'cat': 'csslpTest', 'type': 'mc', 'question': 'Release criteria require no open critical vulnerabilities, but one remains the day before launch and the business wants to proceed. What is the appropriate action?', 'options': ['Get documented acceptance from the accountable owner, with mitigations', 'Remove the vulnerability from the report so that the launch is not delayed', 'Have the project manager approve the exception quietly and note it in the plan', 'Reclassify the vulnerability as low severity so the release criteria are met'], 'correct': 0, 'explanation': 'Releasing with a known critical flaw is a business risk decision that belongs to the accountable owner, made with full information and recorded with mitigations and a plan. Silent exceptions, reclassification and omission undermine integrity of the process.'},
    {'id': 'q61', 'cat': 'csslpTest', 'type': 'mc', 'question': 'A team wants to confirm that its new login feature rejects hostile behavior, such as repeated guesses, tampered tokens and skipped steps. Which testing style does this describe?', 'options': ['Compatibility testing across browsers', 'Usability testing of the login page', 'Load testing to find the throughput limit', 'Negative testing based on abuse cases'], 'correct': 3, 'explanation': 'Negative testing deliberately applies invalid and hostile input and actions to confirm that they are safely refused, often derived from abuse cases. The others test performance, usability and compatibility rather than hostile behavior.'},
    {'id': 'q62', 'cat': 'csslpDeploy', 'type': 'mc', 'question': 'A build server produces release packages that are installed by thousands of customers. Which control BEST lets customers verify that a package really came from the vendor and was not altered?', 'options': ['Post a checksum on the same download page that serves the package', 'Digitally sign the artifact and publish the verification certificate', 'Rename the file with a random version number for each customer', 'Compress the package with a password that is shared by email'], 'correct': 1, 'explanation': 'A digital signature binds the artifact to the publisher and detects tampering, and customers verify it with the published key or certificate. A checksum stored next to the file can be replaced by an attacker, and password compression and renaming do not establish origin or integrity.'},
    {'id': 'q63', 'cat': 'csslpDeploy', 'type': 'mc', 'question': 'An organization wants to limit exposure if a new version has a hidden flaw. Which deployment technique is BEST?', 'options': ['Skipping the staging environment in order to reduce cost', 'A canary release to a small share of users first', 'Disabling monitoring until the release has settled in', 'Deploying to every user at once so the rollout finishes quickly'], 'correct': 1, 'explanation': 'A canary release limits who is affected and provides the chance to detect problems and roll back before wider exposure. Full deployment, skipping staging and disabling monitoring all increase risk.'},
    {'id': 'q64', 'cat': 'csslpDeploy', 'type': 'mc', 'question': 'A review of the delivery pipeline finds that all builds use a long-lived administrator credential stored in the pipeline settings. Which change is MOST important?', 'options': ['Store the credential in the source repository so it is always available', 'Rename the credential so that its administrative purpose is not obvious', 'Share the credential with the operations team to provide some redundancy', 'Use short-lived, narrowly scoped credentials issued per build'], 'correct': 3, 'explanation': 'The pipeline is a high-value target, so credentials should be minimal, temporary and protected, limiting damage if a build is compromised. Renaming gives no protection, sharing widens exposure and storing it in the repository leaks it.'},
    {'id': 'q65', 'cat': 'csslpDeploy', 'type': 'mc', 'question': 'Three vulnerabilities are open: a CVSS 9.8 flaw in an internal tool with no network exposure, a CVSS 7.5 flaw in an internet-facing service listed in the known exploited vulnerabilities catalog, and a CVSS 5.0 flaw in a test server. Which should be addressed FIRST?', 'options': ['The 9.8 flaw in the internal tool, because its base score is the highest', 'The 7.5 flaw in the internet-facing service being exploited in the wild', 'The 5.0 flaw in the test server, because it will be the quickest to fix', 'All three at the same time, in whatever order the team happens to choose'], 'correct': 1, 'explanation': 'Prioritization should combine severity with exposure and exploitation evidence, and active exploitation of an internet-facing system makes the risk immediate. Base score alone ignores context, ease of fixing is not a risk criterion, and refusing to prioritize wastes scarce effort.'},
    {'id': 'q66', 'cat': 'csslpDeploy', 'type': 'mc', 'question': 'A vendor receives a report of a serious flaw from an outside researcher. What is the BEST first step?', 'options': ['Require the researcher to sign an agreement that bans any future disclosure', 'Ignore the report until a customer complains about the same behavior', 'Acknowledge and validate the report, then coordinate the fix with the reporter', 'Publish the technical details at once so that customers can protect themselves'], 'correct': 2, 'explanation': 'A coordinated disclosure process acknowledges, validates and fixes the issue while agreeing a timeline with the reporter. Ignoring invites public disclosure, permanent gag demands damage trust, and publishing details before a fix exposes customers.'},
    {'id': 'q67', 'cat': 'csslpDeploy', 'type': 'mc', 'question': 'A critical patch cannot be applied for two weeks because it requires a long testing cycle on a legacy system. What is the BEST interim step?', 'options': ['Apply the patch to production without any testing in order to close it', 'Turn off the logging that reports the vulnerability on the system', 'Apply compensating controls such as virtual patching and record the exception', 'Ignore the vulnerability and take no action until the patch is ready'], 'correct': 2, 'explanation': 'Compensating controls reduce exposure while the patch is validated, and a documented exception keeps accountability. Ignoring it leaves the risk open, untested patches can break production, and disabling logging hides evidence.'},
    {'id': 'q68', 'cat': 'csslpDeploy', 'type': 'mc', 'question': 'A software product reaches its end-of-life date, and the vendor will stop issuing patches. Which action is MOST appropriate for a customer who depends on it?', 'options': ['Remove its logging in order to improve the performance of the system', 'Continue using it indefinitely on the grounds that it still works correctly', 'Plan migration to a supported product and add compensating controls meanwhile', 'Wait until a breach occurs before beginning any planning for the change'], 'correct': 2, 'explanation': 'Unsupported software accumulates unfixable vulnerabilities, so the right response is to plan retirement or replacement and isolate or protect the system meanwhile. Using it indefinitely, reducing logging and waiting for a breach all raise risk.'},
    {'id': 'q69', 'cat': 'csslpDeploy', 'type': 'mc', 'question': 'Retired application servers are being returned to a leasing company. They held confidential records. Which action is MOST appropriate?', 'options': ['Format the disks with a quick format and reinstall a clean operating system', 'Delete the files and empty the recycle bin on each server before return', 'Remove the asset labels from the servers so they are not identifiable', 'Sanitize the media with a method suited to its sensitivity, and keep a record'], 'correct': 3, 'explanation': 'Sanitization must make data unrecoverable in line with NIST SP 800-88, and records show it was done. Deleting files or quick formatting leaves recoverable data, and removing labels has no effect on data.'},
    {'id': 'q70', 'cat': 'csslpSupply', 'type': 'mc', 'question': 'A new vulnerability is announced in a widely used logging library. What is the BEST way to find out quickly which products are affected?', 'options': ['Wait until customers start to report problems with the products they use', 'Run a performance test on every product in the portfolio', 'Review the marketing material for each of the company products', 'Query the software bill of materials inventory for the library and version'], 'correct': 3, 'explanation': 'An SBOM is exactly the inventory that lets an organization find where a component is used and act fast. Waiting for customers, reading marketing material and running performance tests do not reveal what is inside the software.'},
    {'id': 'q71', 'cat': 'csslpSupply', 'type': 'mc', 'question': 'An SBOM shows a component with a critical vulnerability, but the supplier states that the vulnerable function is never reachable in the product. Which artifact communicates this?', 'options': ['A Common Criteria Protection Profile', 'A software escrow agreement', 'A penetration test report summary', 'A VEX statement'], 'correct': 3, 'explanation': 'A VEX (Vulnerability Exploitability eXchange) document tells consumers whether a known vulnerability actually affects a product, reducing false alarms from SBOM matching. The others are about continuity, evaluation baselines and test results, not exploitability of a specific component vulnerability.'},
    {'id': 'q72', 'cat': 'csslpSupply', 'type': 'mc', 'question': 'A company builds software from internal packages named in a private registry. An attacker publishes a public package with the same name and a higher version number, and the build starts using it. What is this attack?', 'options': ['Cross-site scripting', 'A man-in-the-middle attack on the build network', 'Typosquatting', 'Dependency confusion'], 'correct': 3, 'explanation': 'Dependency confusion exploits package managers that prefer the highest version across registries, so a public package shadows the internal one. Typosquatting relies on misspelled names, which is not happening here, and the others are unrelated attack classes.'},
    {'id': 'q73', 'cat': 'csslpSupply', 'type': 'mc', 'question': 'A team wants to detect newly disclosed vulnerabilities and license problems in the open-source libraries its application uses. Which tool category fits?', 'options': ['Software composition analysis', 'Fuzz testing of the application input handlers', 'Network intrusion detection on the production segment', 'Static application security testing of the code the team wrote'], 'correct': 0, 'explanation': 'SCA identifies third-party and open-source components, their versions, known vulnerabilities and licenses. SAST analyzes the code the team wrote, fuzzing sends malformed input to your code, and intrusion detection monitors network traffic.'},
    {'id': 'q74', 'cat': 'csslpSupply', 'type': 'mc', 'question': 'A proprietary product plans to include a library under a copyleft license that requires derived works to be released under the same license. Which risk should be assessed FIRST?', 'options': ['Usability risk arising from the quality of the library documentation', 'Performance risk from the additional size of the library at runtime', 'Licensing risk that the product may have to be released under copyleft terms', 'Availability risk arising from the update schedule of the library'], 'correct': 2, 'explanation': 'Copyleft terms can oblige distributors to share source code of derivative works, which could conflict with a proprietary model, so license review comes before adoption. The other risks are real but are not the defining concern for this license type.'},
    {'id': 'q75', 'cat': 'csslpSupply', 'type': 'mc', 'question': 'A company must buy a critical component from a new supplier. Which action provides the MOST enforceable assurance of the supplier security practices?', 'options': ['Choose whichever supplier offers the component at the lowest price', 'Put security requirements, breach notification and audit rights in the contract', 'Ask the supplier to complete a short informal questionnaire by telephone', 'Rely on the security statements published on the supplier marketing page'], 'correct': 1, 'explanation': 'Contract terms are enforceable and give the buyer recourse, and a right to audit lets them verify claims. Marketing, verbal assurances and price offer no enforceable security commitment.'},
    {'id': 'q76', 'cat': 'csslpSupply', 'type': 'mc', 'question': 'A customer needs assurance that it can keep maintaining a mission-critical custom application if the vendor goes out of business. Which arrangement addresses this?', 'options': ['A non-disclosure agreement signed by the key vendor staff members', 'A longer warranty on the hardware that the application runs on', 'An additional penetration test carried out each year by an outside firm', 'Software escrow, with the deposit verified to build correctly'], 'correct': 3, 'explanation': 'Escrow releases source code and build materials to the customer upon defined events such as insolvency, and verification confirms the deposit is usable. Hardware warranties, NDAs and penetration tests do not preserve the ability to maintain the software.'},
    {'id': 'q77', 'cat': 'csslpSupply', 'type': 'mc', 'question': 'A buyer is comparing two products evaluated under Common Criteria, one at EAL2 and one at EAL4. What does the higher level indicate?', 'options': ['A guarantee that the product contains no remaining vulnerabilities', 'Certification of the vendor to handle all classified information', 'More rigorous evaluation of design, testing and development processes', 'A larger number of security features is built into the product'], 'correct': 2, 'explanation': 'An evaluation assurance level measures the depth and rigor of evaluation against the Security Target, not how many features the product has. No level guarantees absence of vulnerabilities, and the level is unrelated to handling classified information.'},
    {'id': 'msq1', 'cat': 'csslpConcepts', 'type': 'ms', 'question': 'Which TWO principles are both violated when a web service runs as an administrator and also skips authorization checks on internal calls because the caller is on the internal network? (Choose two.)', 'options': ['Economy of mechanism', 'Least privilege', 'Complete mediation', 'Open design', 'Psychological acceptability'], 'correct': [1, 2], 'explanation': 'Running with administrator rights gives the service more access than it needs, which violates least privilege, and trusting internal callers without checking each access violates complete mediation. Psychological acceptability concerns usability, open design concerns secrecy of the design, and economy of mechanism concerns simplicity, none of which are described.'},
    {'id': 'msq2', 'cat': 'csslpConcepts', 'type': 'ms', 'question': 'Which TWO statements about risk treatment are correct? (Choose two.)', 'options': ['Accepting a risk should be a documented decision by an accountable owner who understands the exposure', 'Mitigating a risk eliminates the threat completely', 'Avoiding a risk means installing a control that reduces its likelihood', 'Accepting a risk is the default outcome when no one responds to a finding', 'Transferring risk, such as through insurance or a contract, shifts financial impact but not the accountability for the decision'], 'correct': [0, 4], 'explanation': 'Transfer moves some financial consequence to another party while the organization remains accountable, and acceptance is only valid when an informed owner decides and records it. Avoidance means stopping the risky activity rather than adding a control, mitigation reduces but does not eliminate risk, and inaction is not an informed acceptance.'},
    {'id': 'msq3', 'cat': 'csslpLifecycle', 'type': 'ms', 'question': 'Which TWO of the following are prescriptive frameworks that tell an organization what secure development activities to adopt? (Choose two.)', 'options': ['CVSS', 'BSIMM', 'NIST SSDF', 'OWASP SAMM', 'SPDX'], 'correct': [2, 3], 'explanation': 'SAMM and the SSDF prescribe practices and, in SAMM, maturity levels to aim for. BSIMM is descriptive and reports what other organizations do, CVSS scores vulnerability severity, and SPDX is a format for software inventories.'},
    {'id': 'msq4', 'cat': 'csslpLifecycle', 'type': 'ms', 'question': 'Which TWO actions BEST adapt a secure SDLC to a fast agile and DevOps delivery model? (Choose two.)', 'options': ['Move security requirements into a document that is not updated', 'Require a signed paper approval from the board before every sprint', 'Add security acceptance criteria to the definition of done for each story', 'Embed automated static analysis and dependency scanning in the pipeline', 'Perform one manual penetration test at the end of the project'], 'correct': [2, 3], 'explanation': 'Automated checks and testable acceptance criteria scale with fast iteration and provide continuous feedback. A single end-of-project test, per-sprint board approval and a static requirements document either arrive too late or are impractical at that speed.'},
    {'id': 'msq5', 'cat': 'csslpReq', 'type': 'ms', 'question': 'Which TWO factors should drive the security requirements for an application that stores health records of patients in several countries? (Choose two.)', 'options': ['The data classification and sensitivity of the records', 'The color scheme of the user interface', 'The privacy and health laws that apply to those patients', 'The vendor of the monitors in the office', 'The preferred programming language of the team'], 'correct': [0, 2], 'explanation': 'Requirements come from what the data is and what laws and contracts govern it. Language preference, interface design and office equipment can influence implementation but do not set the required security and privacy controls.'},
    {'id': 'msq6', 'cat': 'csslpReq', 'type': 'ms', 'question': 'Which THREE items would normally be captured in logging requirements for an application? (Choose three.)', 'options': ['Which security events must be recorded, such as login failures and privilege changes', 'That every user keystroke must be recorded in plain text', 'That logs may be edited by developers to remove embarrassing entries', 'That passwords and full payment card numbers must never be written to logs', 'How long logs must be retained and how they are protected from tampering'], 'correct': [0, 3, 4], 'explanation': 'Good logging requirements say what to log, how long to keep it and how to protect it, and exclude sensitive data. Recording all keystrokes creates a privacy and security hazard and editable logs defeat accountability.'},
    {'id': 'msq7', 'cat': 'csslpReq', 'type': 'ms', 'question': 'Which TWO are valid sources of abuse and misuse cases? (Choose two.)', 'options': ['Outputs of threat modeling for the same feature', 'The firmware version of the build server', 'The monthly cloud billing report', 'Brainstorming with stakeholders about how an attacker would subvert a feature'], 'correct': [0, 3], 'explanation': 'Abuse cases come from adversarial thinking and structured threat analysis of the feature. Billing reports and build server firmware have no direct connection to how a feature could be abused.'},
    {'id': 'msq8', 'cat': 'csslpDesign', 'type': 'ms', 'question': 'Which TWO are benefits of attack surface reduction? (Choose two.)', 'options': ['Removal of the need for authentication on remaining features', 'A guarantee that no vulnerabilities remain', 'Fewer entry points that an attacker can probe', 'Automatic compliance with every regulation', 'Less code and configuration to maintain and defend'], 'correct': [2, 4], 'explanation': 'Removing unneeded features, ports and accounts shrinks what must be tested and defended. It does not guarantee a vulnerability-free product, it does not remove the need to authenticate the remaining functions, and compliance requires more than a smaller surface.'},
    {'id': 'msq9', 'cat': 'csslpDesign', 'type': 'ms', 'question': 'Which TWO design measures address threats of spoofing and elevation of privilege respectively? (Choose two.)', 'options': ['Strong authentication, such as multi-factor authentication', 'Encrypting data at rest', 'Authorization checks that enforce least privilege on every request', 'Rate limiting on public endpoints', 'Digital signatures on log files'], 'correct': [0, 2], 'explanation': 'Spoofing is answered by authentication, and elevation of privilege by authorization with least privilege. Signing logs addresses tampering and repudiation, rate limiting addresses denial of service, and encryption at rest addresses information disclosure.'},
    {'id': 'msq10', 'cat': 'csslpDesign', 'type': 'ms', 'question': 'Which TWO are appropriate controls when designing a serverless function that processes events from a public queue? (Choose two.)', 'options': ['Validate every event as untrusted input', 'Share one broad administrator role among all the functions', 'Give each function its own narrowly scoped identity', 'Embed secrets in the function source for speed'], 'correct': [0, 2], 'explanation': 'Event sources are inputs that attackers can influence and per-function identities with minimal permissions limit damage. A shared broad role and embedded secrets both violate least privilege and secrets handling.'},
    {'id': 'msq11', 'cat': 'csslpImpl', 'type': 'ms', 'question': 'Which TWO measures together best prevent SQL injection and cross-site scripting in a web application? (Choose two.)', 'options': ['Longer session timeouts', 'Context-aware output encoding when displaying data', 'Parameterized queries for database access', 'Hiding the server version banner', 'Disabling the audit log'], 'correct': [1, 2], 'explanation': 'Parameterization prevents data being interpreted as SQL and output encoding prevents data being interpreted as script. Session timeouts, disabled logging and banner hiding do not address either attack at its root.'},
    {'id': 'msq12', 'cat': 'csslpImpl', 'type': 'ms', 'question': 'Which TWO are correct practices for secrets management? (Choose two.)', 'options': ['Keep secrets in environment-specific configuration files in the repository', 'Store secrets in a dedicated manager with access control, rotation and auditing', 'Share one service account password among all developers', 'Rotate any secret that has ever been committed to a repository'], 'correct': [1, 3], 'explanation': 'A secrets manager centralizes control and a leaked secret must be considered compromised. Committing configuration with secrets and sharing one password both create exposure and remove accountability.'},
    {'id': 'msq13', 'cat': 'csslpTest', 'type': 'ms', 'question': 'Which TWO statements correctly contrast static and dynamic application security testing? (Choose two.)', 'options': ['Static testing examines code without running it and can identify the line with the flaw', 'Dynamic testing probes a running application and can reveal runtime and configuration issues', 'Dynamic testing identifies the exact source file and line for each finding', 'Static testing requires a deployed environment with user traffic'], 'correct': [0, 1], 'explanation': 'Static testing works on code and gives locations, while dynamic testing works on the running system and finds issues visible only at runtime. The reversed statements are common mistakes.'},
    {'id': 'msq14', 'cat': 'csslpTest', 'type': 'ms', 'question': 'Which THREE are characteristics of an effective penetration test engagement? (Choose three.)', 'options': ['A report with findings, evidence and remediation advice', 'Testers who actively attempt to exploit weaknesses to show impact', 'Immediate public release of findings', 'A written scope and authorization before testing begins', 'Testing of any system the testers find, regardless of the scope'], 'correct': [0, 1, 3], 'explanation': 'A penetration test is authorized, scoped, exploitation-oriented and ends in actionable reporting. Testing outside the agreed scope can be illegal, and findings are confidential until fixed.'},
    {'id': 'msq15', 'cat': 'csslpTest', 'type': 'ms', 'question': 'Which TWO practices reduce the risk of using test environments? (Choose two.)', 'options': ['Use synthetic or masked data in place of production records', 'Give all employees access for convenience', 'Keep the test systems unpatched since they are not production', 'Apply access control and monitoring to test systems'], 'correct': [0, 3], 'explanation': 'Test systems often hold copies of real data and are weakly protected, so masking data and applying access control close the gap. Open access and no patching enlarge the exposure.'},
    {'id': 'msq16', 'cat': 'csslpDeploy', 'type': 'ms', 'question': 'Which TWO are elements of a secure CI/CD pipeline? (Choose two.)', 'options': ['Disabling build logging to save storage', 'A single shared administrator account for every pipeline job', 'Isolated, ephemeral build runners with short-lived credentials', 'Signed build artifacts with access-controlled and logged pipeline changes'], 'correct': [2, 3], 'explanation': 'Isolation and short-lived credentials limit what a compromised job can do, and signing with controlled changes protects integrity. A shared administrator account and no logs both make compromise easier and harder to detect.'},
    {'id': 'msq17', 'cat': 'csslpDeploy', 'type': 'ms', 'question': 'Which TWO should be considered when prioritizing which vulnerabilities to fix first? (Choose two.)', 'options': ['The exposure and business criticality of the affected system', 'Which vulnerability was found by the most senior tester', 'The order in which the findings appear in the report', 'Evidence that the vulnerability is being actively exploited'], 'correct': [0, 3], 'explanation': 'Risk-based prioritization uses exploitation evidence, exposure and criticality in addition to base severity. Who found a flaw and report order say nothing about risk.'},
    {'id': 'msq18', 'cat': 'csslpSupply', 'type': 'ms', 'question': 'Which TWO are effective defenses against dependency confusion attacks? (Choose two.)', 'options': ['Pin dependency versions with lock files and verify package hashes', 'Allow builds to pull from any public registry in any order', 'Reserve or scope internal package names and configure the build to resolve them only from the private registry', 'Always install the latest version of every package automatically'], 'correct': [0, 2], 'explanation': 'Controlling where internal names resolve and pinning with hashes stops substitution by a malicious higher-version package. Taking the latest version automatically and unrestricted resolution are the conditions the attack exploits.'},
    {'id': 'tf1', 'cat': 'csslpConcepts', 'type': 'tf', 'question': 'An application that has successfully authenticated a user has therefore authorized that user to perform any action the application offers.', 'answer': False, 'explanation': 'Authentication establishes identity only; authorization is a separate decision about what that identity may do, and it must be checked for each request according to the user permissions.'},
    {'id': 'tf2', 'cat': 'csslpConcepts', 'type': 'tf', 'question': 'Defense in depth means layering independent controls so that the failure of one control does not by itself expose the asset.', 'answer': True, 'explanation': 'Independent layers, such as input validation, authorization, encryption and monitoring, mean one failure is not enough for compromise. The layers must not share the same weakness or they add little.'},
    {'id': 'tf3', 'cat': 'csslpConcepts', 'type': 'tf', 'question': 'Encrypting a message with a symmetric key that two parties share provides non-repudiation of who sent it.', 'answer': False, 'explanation': 'Either holder of the shared key could have produced the message, so neither can be proven to have sent it. Non-repudiation requires something unique to one party, such as an asymmetric digital signature, plus trustworthy logging.'},
    {'id': 'tf4', 'cat': 'csslpConcepts', 'type': 'tf', 'question': 'Under the open design principle, a well-designed security mechanism should stay secure even if everything about it except the keys is public knowledge.', 'answer': True, 'explanation': 'Security should rest on protecting keys and other secrets, not on secrecy of the design. Obscurity can be a minor extra layer but fails once the design leaks or is reverse engineered.'},
    {'id': 'tf5', 'cat': 'csslpLifecycle', 'type': 'tf', 'question': 'BSIMM tells an organization which security activities it must perform in order to be compliant.', 'answer': False, 'explanation': 'BSIMM is descriptive: it reports what participating organizations observably do so a firm can compare itself. Prescriptive models such as SAMM and the SSDF tell organizations what to adopt.'},
    {'id': 'tf6', 'cat': 'csslpLifecycle', 'type': 'tf', 'question': 'Finding and fixing a security defect during requirements or design is generally far cheaper than fixing it after release.', 'answer': True, 'explanation': 'The cost to correct a defect grows as it moves through the lifecycle, because more work depends on it and deployed fixes require patching and customer disruption. This is the rationale for shifting security left.'},
    {'id': 'tf7', 'cat': 'csslpLifecycle', 'type': 'tf', 'question': 'A security gate that any project manager can routinely waive without recorded justification still provides strong assurance.', 'answer': False, 'explanation': 'A gate only has value when it has clear criteria and a controlled exception process. Routine, unrecorded waivers mean nobody is actually accountable for the residual risk.'},
    {'id': 'tf8', 'cat': 'csslpLifecycle', 'type': 'tf', 'question': 'Emergency changes may skip change management entirely, since speed is more important than documentation.', 'answer': False, 'explanation': 'Emergency changes follow an expedited process with delegated approval and are documented and reviewed afterward. Skipping the process removes accountability and the ability to learn from the change.'},
    {'id': 'tf9', 'cat': 'csslpReq', 'type': 'tf', 'question': 'Security requirements are best identified early in the lifecycle, because requirements that are never stated are rarely designed, built or tested.', 'answer': True, 'explanation': 'Requirements drive design and testing. A control that is not specified is easily missed and expensive to add later.'},
    {'id': 'tf10', 'cat': 'csslpReq', 'type': 'tf', 'question': 'Pseudonymized personal data can usually be re-identified with additional information, so it is generally still treated as personal data under privacy regulations.', 'answer': True, 'explanation': 'Under regimes such as GDPR pseudonymized data remains personal data because the link to the individual can be restored. Only data that cannot reasonably be re-identified is anonymous.'},
    {'id': 'tf11', 'cat': 'csslpReq', 'type': 'tf', 'question': 'Under FIPS 199, the overall impact category of a system is the highest impact level among confidentiality, integrity and availability.', 'answer': True, 'explanation': 'The high-water mark rule means a single high impact rating on any of the three properties makes the overall category high, which in turn selects a stronger control baseline.'},
    {'id': 'tf12', 'cat': 'csslpReq', 'type': 'tf', 'question': 'An RTO states how much data loss is tolerable, while an RPO states how long a restoration may take.', 'answer': False, 'explanation': 'The definitions are reversed. RTO is the maximum acceptable time to restore service and RPO is the maximum acceptable data loss, measured as a period of time.'},
    {'id': 'tf13', 'cat': 'csslpDesign', 'type': 'tf', 'question': 'STRIDE is used to classify threats into categories, while DREAD is used to rate them so they can be prioritized.', 'answer': True, 'explanation': 'STRIDE names the categories (spoofing, tampering, repudiation, information disclosure, denial of service, elevation of privilege) and DREAD scores damage, reproducibility, exploitability, affected users and discoverability. Candidates often swap the two roles.'},
    {'id': 'tf14', 'cat': 'csslpDesign', 'type': 'tf', 'question': 'In a zero trust architecture, a request from a device inside the corporate network is trusted by default.', 'answer': False, 'explanation': 'Zero trust removes implicit trust based on network location. Each request is authenticated, authorized and evaluated using identity, device state and context.'},
    {'id': 'tf15', 'cat': 'csslpDesign', 'type': 'tf', 'question': 'OAuth 2.0 on its own is an authorization framework and not an authentication protocol.', 'answer': True, 'explanation': 'OAuth 2.0 grants delegated access to resources through tokens. Authentication of the user is provided by a layer above it such as OpenID Connect.'},
    {'id': 'tf16', 'cat': 'csslpDesign', 'type': 'tf', 'question': 'Because containers share the host kernel, they generally provide weaker isolation between workloads than separate virtual machines.', 'answer': True, 'explanation': 'A flaw in the shared kernel can affect every container on the host, so extra measures such as non-root users, restricted capabilities and network policies matter.'},
    {'id': 'tf17', 'cat': 'csslpDesign', 'type': 'tf', 'question': 'In a shared responsibility model for cloud, the customer is no longer responsible for its data once it is stored in the provider platform.', 'answer': False, 'explanation': 'The provider secures the infrastructure and, depending on the service model, parts of the platform, but customers remain responsible for their data, identities, access configuration and the security of their own code.'},
    {'id': 'tf18', 'cat': 'csslpImpl', 'type': 'tf', 'question': 'Client-side input validation is sufficient to protect an application from malicious input, because the user interface will reject bad data.', 'answer': False, 'explanation': 'Attackers can bypass the client entirely and send requests directly, so validation must be enforced on the server. Client-side checks are a usability aid only.'},
    {'id': 'tf19', 'cat': 'csslpImpl', 'type': 'tf', 'question': 'Address space layout randomization removes buffer overflow vulnerabilities from a program.', 'answer': False, 'explanation': 'ASLR makes exploitation harder by randomizing memory layout, but the overflow remains. The fix is bounds checking or using a memory-safe language.'},
    {'id': 'tf20', 'cat': 'csslpImpl', 'type': 'tf', 'question': 'Passwords should be stored using a reversible encryption scheme so that support staff can recover them for users who forget them.', 'answer': False, 'explanation': 'Passwords should be hashed with a unique salt using a slow algorithm. They should never need to be recovered, and reversible storage exposes every password if the key is taken.'},
    {'id': 'tf21', 'cat': 'csslpImpl', 'type': 'tf', 'question': 'An access key that was committed to a repository and quickly deleted can safely be considered secret again.', 'answer': False, 'explanation': 'Clones, caches and history can all retain the value, so the key must be treated as compromised, revoked and rotated.'},
    {'id': 'tf22', 'cat': 'csslpImpl', 'type': 'tf', 'question': 'Hiding a link from the user interface is an adequate access control for an administrative function.', 'answer': False, 'explanation': 'Access control must be enforced on the server for each request. A hidden link can be found or guessed, and an unprotected endpoint can be called directly.'},
    {'id': 'tf23', 'cat': 'csslpTest', 'type': 'tf', 'question': 'Dynamic application security testing can be performed against a running application even when no source code is available.', 'answer': True, 'explanation': 'DAST works from outside on a running application, like an attacker, and needs no source code. It is static analysis that examines source, and it can point to the line of code.'},
    {'id': 'tf24', 'cat': 'csslpTest', 'type': 'tf', 'question': 'Fuzz testing is particularly effective at finding input handling and memory safety flaws in parsers.', 'answer': True, 'explanation': 'Fuzzers produce large volumes of malformed input and watch for crashes and hangs, which often indicate memory corruption or unhandled cases.'},
    {'id': 'tf25', 'cat': 'csslpTest', 'type': 'tf', 'question': 'A high code coverage percentage proves that the tests check security behavior correctly.', 'answer': False, 'explanation': 'Coverage shows which code ran during tests, not whether the tests make meaningful checks. Security test cases must also address abuse cases and error paths.'},
    {'id': 'tf26', 'cat': 'csslpTest', 'type': 'tf', 'question': 'A penetration test may be started on a production system once the testers verbally agree on what to test.', 'answer': False, 'explanation': 'Testing needs written authorization from the owner and agreed rules of engagement defining scope and limits, to protect both parties and avoid unintended damage.'},
    {'id': 'tf27', 'cat': 'csslpTest', 'type': 'tf', 'question': 'Real production customer data may be loaded into a less protected test environment as long as the test network is internal.', 'answer': False, 'explanation': 'Test systems typically have weaker controls, so production personal data must be replaced with synthetic or masked data regardless of the network.'},
    {'id': 'tf28', 'cat': 'csslpDeploy', 'type': 'tf', 'question': 'A digital signature on a software release shows who published it and that it was not altered after signing, but not that it is free of vulnerabilities.', 'answer': True, 'explanation': 'A signature proves the publisher and integrity since signing. A signed artifact can still contain flaws, or malicious code if the signing process itself was compromised.'},
    {'id': 'tf29', 'cat': 'csslpDeploy', 'type': 'tf', 'question': 'The CVSS base score alone is a reliable measure of the risk a vulnerability poses to a specific organization.', 'answer': False, 'explanation': 'CVSS measures intrinsic severity. Risk also depends on exposure, exploitation activity, compensating controls and the criticality of the affected asset.'},
    {'id': 'tf30', 'cat': 'csslpDeploy', 'type': 'tf', 'question': 'Deleting files or performing a quick format is an acceptable way to sanitize storage that held confidential data before it leaves the organization.', 'answer': False, 'explanation': 'These actions normally leave recoverable data. Sanitization should follow a method such as NIST SP 800-88 clear, purge or destroy, chosen by data sensitivity and media type.'},
    {'id': 'tf31', 'cat': 'csslpDeploy', 'type': 'tf', 'question': 'Software that has reached end of life may contain known vulnerabilities that the vendor will no longer fix.', 'answer': True, 'explanation': 'After end of life the vendor stops providing patches, so newly discovered flaws remain open. Customers must migrate or isolate the software and add compensating controls.'},
    {'id': 'tf32', 'cat': 'csslpSupply', 'type': 'tf', 'question': 'An SBOM alone tells an organization whether each listed component is exploitable in the product.', 'answer': False, 'explanation': 'An SBOM is an inventory of components and versions. Determining exploitability requires vulnerability data and, for example, a VEX statement from the supplier.'},
    {'id': 'tf33', 'cat': 'csslpSupply', 'type': 'tf', 'question': 'Dependency pinning and verifying hashes help defend against malicious package substitution.', 'answer': True, 'explanation': 'Pinned versions with recorded hashes mean the build only accepts the exact artifact that was reviewed, blocking a newly published malicious look-alike or higher version.'},
    {'id': 'tf34', 'cat': 'csslpSupply', 'type': 'tf', 'question': 'A higher Common Criteria evaluation assurance level means the product has more security features than a lower-level product.', 'answer': False, 'explanation': 'The level reflects the rigor and depth of the evaluation, giving more confidence that the stated security functions work, not how many functions exist.'},
]

LESSONS = [
    {'id': 'secure-software-concepts', 'title': 'Secure Software Concepts and Design Principles', 'summary': 'The core security properties, the classic secure design principles, and the risk and privacy ideas that every other domain builds on.', 'diagram': 'cswPrinciples', 'vocabIds': ['f1', 'f3', 'f5', 'f7', 'f9', 'f11', 'f13', 'f15'], 'quizIds': ['q1', 'q4', 'q7', 'tf1', 'msq1'], 'reading': 'Secure software starts from a small set of ideas. The first is the CIA triad: confidentiality (only the right people see the data), integrity (the data is only changed in authorized ways) and availability (the system works when it is needed). Every threat you will ever model attacks one of these, and every control you will ever choose protects one of these. Next to the triad sit the AAA steps. Authentication proves who is asking, authorization decides what that identity may do, and accountability records what it actually did. A very common exam trap is to treat a valid login as permission. Being authenticated says nothing about whether you may read a particular record.\n\nThe secure design principles come largely from a famous 1975 paper by Saltzer and Schroeder, and they are still the vocabulary of the exam. Least privilege means every user and every piece of code gets only the access it needs. Separation of duties means one person cannot complete a sensitive process alone. Defense in depth means several independent controls, so one failure is not a disaster. Fail-safe defaults means that access is denied unless it is explicitly granted and that a failing component ends up closed, not open. Complete mediation means every access is checked every time, not just once at the start of a session. Economy of mechanism says keep security mechanisms small and simple, because simple things can be verified. Open design says do not rely on keeping the design secret, only the keys. Psychological acceptability says that if a control is painful, people will route around it.\n\nTwo more are worth knowing. Least common mechanism says to minimize shared components between users, because shared state is a path for leaks. Separation of privilege says that sensitive actions should need more than one condition to be satisfied. A service running as an administrator breaks least privilege. A gateway that opens when its configuration fails breaks fail-safe defaults. An API that checks permission only when a session begins breaks complete mediation.\n\nThe next layer is risk. A threat is something that could cause harm, a vulnerability is a weakness it could exploit, and risk is the combination of likelihood and impact. Organizations can mitigate a risk with controls, transfer it with insurance or contract, avoid it by dropping the activity, or accept it knowingly. Acceptance is a decision by an accountable owner, written down, not what happens when nobody acts. For quantitative questions, remember that single loss expectancy is asset value times exposure factor, and annualized loss expectancy is that figure times the annual rate of occurrence. A safeguard is worth buying when it reduces the expected annual loss by more than it costs per year.\n\nFinally, modern secure software work includes privacy and product responsibility. Privacy by design means collecting only what you need, making privacy the default, and protecting data through its entire life. Secure by design and secure by default shift responsibility toward the vendor: the product should be built with security in its architecture and ship hardened, rather than shipping insecure and publishing a guide for customers to fix it.', 'fundamentalsLabel': 'New to secure design principles? See the everyday analogy', 'fundamentals': 'Think of a well-run bank branch. Tellers can only open the drawer they are assigned (least privilege), large withdrawals need a second signature (separation of duties), and there is a door, a camera, a vault and an alarm instead of one lock (defense in depth). If the power fails, the vault stays locked (fail-safe defaults) and every withdrawal is checked against the account at the moment it is made, not because the customer was recognized at the door (complete mediation). The vault design is not secret, since the safety rests on the combination (open design), and the procedures are simple enough that staff actually follow them (economy of mechanism and psychological acceptability).', 'keyTerms': ['CIA triad', 'AAA', 'Least privilege', 'Separation of duties', 'Defense in depth', 'Fail-safe defaults', 'Complete mediation', 'Open design', 'Risk treatment'], 'commonTraps': ['Authentication is not authorization: a successful login does not grant access to every function or record.', 'Fail safe protects human life (doors unlock in a fire), while fail secure protects data (doors lock); software questions normally mean fail secure, which is the default-deny idea.', 'Least privilege trims each role to the minimum, whereas separation of duties splits a single sensitive process across roles; they are often swapped in distractors.', 'Risk acceptance is a documented decision by an informed accountable owner, not a lack of action, and transfer shifts financial impact but not accountability.'], 'scenario': 'A team ships a reporting service that runs under a database owner account, caches each user permissions at login for the whole day, and reveals a full stack trace to anyone who triggers an error. Naming the principles at play makes the remediation obvious: reduce the account to read-only access on the views it needs (least privilege), check authorization on each request (complete mediation), and show a generic message while logging the detail (fail-safe handling and open design, since the system should not depend on attackers not seeing its internals).', 'onTheJob': 'Practitioners rarely cite Saltzer and Schroeder by name, but the principles are the shared language in design reviews: saying this call path lacks complete mediation gets a faster fix than saying it feels insecure. Keep a short list of the principles in your review checklist and map every finding to one. When you present risk to management, always attach an owner and a decision (mitigate, transfer, avoid, accept) to each item, because a risk list with no owners becomes a graveyard. And remember that the exam rewards the answer that fixes the root cause by design over the answer that adds a compensating control after the fact.'},
    {'id': 'secure-lifecycle-management', 'title': 'Secure Lifecycle Management: Models, Maturity and Governance', 'summary': 'How security is built into the software development lifecycle, the main frameworks and maturity models, and the governance that keeps them running.', 'diagram': 'cswSdlc', 'vocabIds': ['f17', 'f18', 'f20', 'f22', 'f24', 'f25', 'f27', 'f29'], 'quizIds': ['q11', 'q13', 'q16', 'tf5', 'msq3'], 'reading': 'A secure software development lifecycle (secure SDLC) is not a separate process bolted onto development. It is the practice of placing security activities inside every phase: security requirements during planning, threat modeling during design, secure coding and review during implementation, security testing before release, and monitoring and response afterward. The guiding idea is shift left. A defect found while requirements are being written costs a conversation to fix, while the same defect found in production costs an emergency patch, customer notification and possibly a breach. That cost curve is the standard justification you will see behind exam answers that favor earlier activities.\n\nSeveral frameworks give structure, and the exam expects you to tell them apart. The Microsoft Security Development Lifecycle (SDL) is a prescriptive set of practices from training through requirements, design, implementation, verification, release and response. The NIST Secure Software Development Framework (SSDF, SP 800-218) groups practices into four sets, Prepare the Organization, Protect the Software, Produce Well-Secured Software and Respond to Vulnerabilities, and it works with any lifecycle model. OWASP SAMM, the Software Assurance Maturity Model, is also prescriptive and organizes work into five business functions: governance, design, implementation, verification and operations, each with three practices and three maturity levels. BSIMM is different in kind: it is descriptive. It records what real organizations do, so you use it to compare your program with peers, not to learn what you should do.\n\nThe development model changes how security is scheduled, not whether it happens. In waterfall, security activities map to phase gates. In agile, security must be expressed as user stories and acceptance criteria, tested within the sprint, and automated wherever possible. In DevOps and DevSecOps, security checks such as static analysis, dependency scanning and policy checks run in the delivery pipeline, and ownership of security is shared between development, operations and security staff.\n\nGovernance is what makes the practices stick. A policy states management intent and is mandatory, a standard states specific mandatory requirements, a guideline offers optional advice, and a procedure lists steps. Role-based training makes sure developers, testers, architects and operators each know what they need. Gates define criteria that must be met before work moves on, and an exception to a gate needs a documented risk acceptance from the accountable owner.\n\nFinally, programs must be measured and changes controlled. Useful metrics are trends, such as mean time to remediate by severity, the percentage of code covered by scanning and the number of open findings by severity, because a raw count of vulnerabilities can rise when testing improves. Change management ensures that every change, including security fixes, is assessed, approved, tested and recorded. Emergencies get an expedited path with delegated approval and a review afterward, not a bypass.', 'fundamentalsLabel': 'New to secure lifecycle models? See the everyday analogy', 'fundamentals': 'Building secure software is like building a house. You do not inspect the electrical wiring only after the walls are plastered; the inspector visits at the foundation, framing and wiring stages, and each visit has criteria that must pass before the next trade starts (gates). A building code states what is required (standards), best-practice guides suggest more (guidelines), and the contractor follows detailed instructions (procedures). A maturity model is like grading the contractor on how repeatable their process is, and a benchmark study such as BSIMM is like a survey of what other contractors in town actually do.', 'keyTerms': ['Secure SDLC', 'Shift left', 'Microsoft SDL', 'NIST SSDF', 'OWASP SAMM', 'BSIMM', 'DevSecOps', 'Security champions', 'Maturity model'], 'commonTraps': ['BSIMM is descriptive (what others do) while SAMM, the SDL and the SSDF are prescriptive (what to do); questions often hinge on that single word.', 'The SSDF has four groups: prepare, protect, produce and respond; it is outcome-based and is not a lifecycle model in itself.', 'A higher maturity level means the process is managed and repeatable, not that the resulting software is secure.', 'Emergency changes still follow an expedited process with approval and later review; skipping change management is never the best answer.'], 'scenario': 'A company moving to continuous delivery asks what to do about its annual manual security review. A good answer keeps the review for architecture and risk questions but moves repeatable checks into the pipeline: static analysis and dependency scanning on every commit, security acceptance criteria in every story, and a gate that blocks release when critical findings are open without an approved exception. It then measures mean time to remediate by severity and uses SAMM to plan the next maturity step.', 'onTheJob': 'Programs fail from friction more often than from missing tools. Introduce checks in advisory mode first, tune them until developers trust the findings, then turn them into gates. Pick a small number of metrics tied to outcomes, such as time to fix critical findings, and review them with engineering leaders each quarter. Use BSIMM or SAMM to justify budget by showing the gap to peers and a concrete roadmap, not to chase a score. Keep a written exception process, because there will always be a launch with an open finding, and you want the business owner, not the security team, to be the one accepting that risk in writing.'},
    {'id': 'secure-software-requirements', 'title': 'Secure Software Requirements: Security, Privacy and Compliance', 'summary': 'How to elicit, classify and document security, privacy and compliance requirements, including abuse cases and traceability.', 'diagram': 'cswAbuse', 'vocabIds': ['f31', 'f33', 'f35', 'f37', 'f39', 'f41', 'f43', 'f45'], 'quizIds': ['q19', 'q22', 'q25', 'tf9', 'msq5'], 'reading': 'Requirements are where security either gets specified or gets forgotten. Functional requirements describe what the software does, and non-functional requirements describe qualities such as performance, availability and security. A control that is not written down will rarely be designed, built or tested, which is why the exam keeps returning to the idea that missing security requirements should be elicited first, before anyone argues about tools. Good requirements are specific and testable. The statement that the system must be secure cannot be tested, but a statement such as all inputs are validated on the server and every request is authorized for the specific object can be.\n\nSources of security requirements include the data classification, the laws and contracts that apply, the organization policies and standards, the results of threat modeling, and abuse cases. Data classification assigns levels such as public, internal, confidential and restricted, and it is decided by the data owner, not by developers. The level then drives encryption, access control, logging, retention and handling rules. For federal systems FIPS 199 rates the impact of losing confidentiality, integrity and availability as low, moderate or high and uses the high-water mark, so one high rating makes the overall system high. The data lifecycle matters too: create, store, use, share, archive and destroy are all stages with requirements, and backups and test copies are the places where data most often escapes.\n\nAbuse and misuse cases flip a use case around. Where a use case says a customer places an order, an abuse case says an attacker places thousands of orders with stolen cards, or changes the order number to read someone else\'s order. They produce requirements such as rate limiting, fraud checks and object-level authorization, and later become negative test cases. A security requirements traceability matrix links each requirement to its source, design element, code and test, so you can show coverage and see what a change affects.\n\nPrivacy and compliance are requirements too. Privacy requirements include data minimization (collect only what you need), purpose limitation (use data only for the declared purpose), retention limits and deletion, and a privacy or data protection impact assessment performed early for high-risk processing. Laws and standards differ: GDPR governs personal data of people in the EU, HIPAA covers US health information, PCI DSS is an industry standard for payment card data enforced by contract, and SOX concerns controls over financial reporting. The first step is to determine which apply, then map them to concrete controls.\n\nFinally, availability and recovery needs belong in requirements. The recovery time objective is the longest tolerable time to restore service, and the recovery point objective is the longest tolerable window of data loss. Remember the reversal trap: RTO is time to recover, RPO is how far back data may go. Logging requirements say which events are recorded, what each record contains, how long logs are kept and how they are protected, and they exclude secrets such as passwords.', 'fundamentalsLabel': 'New to security requirements? See the everyday analogy', 'fundamentals': 'Writing security requirements is like writing the brief for a new office building. Saying the building should be safe is useless to the architect. A good brief says which rooms hold valuables (data classification), which fire and accessibility codes apply (compliance), who must be able to enter which floors (access requirements), how long the building may be closed after a flood (recovery objectives) and what a burglar might try, such as using the loading dock or tailgating (abuse cases). A checklist that ties each line of the brief to a drawing and an inspection is the traceability matrix.', 'keyTerms': ['Non-functional requirement', 'Data classification', 'Abuse case', 'SRTM', 'FIPS 199', 'Data minimization', 'DPIA', 'RTO and RPO', 'ASVS'], 'commonTraps': ['RTO is the time allowed to restore service and RPO is the amount of data loss allowed; the two are swapped constantly in answer options.', 'Data classification is performed by the data owner and drives controls; it is not chosen by whichever team finds a control cheapest.', 'Pseudonymized data is generally still personal data under GDPR; only truly anonymized data is outside it.', 'PCI DSS is a contractual industry standard, not a statute, yet compliance is still mandatory for organizations that handle card data.'], 'scenario': 'A health-tech startup is building a mobile app that stores diagnoses and appointment times for users in several countries. Before design begins the team has the data owner classify each field, identifies the health and privacy laws that apply, runs a data protection impact assessment, writes abuse cases such as one patient reading another record, and records requirements for encryption, access control, logging and retention. Each requirement is entered in a traceability matrix with an owner and a planned test.', 'onTheJob': 'The most valuable skill is turning vague demands into testable statements and getting them into the backlog before sprint planning, not after. Ask what is the worst thing that could happen to this data, then write that as an abuse case. Keep a short mapping from each regulation to the controls that satisfy it, so audits become a lookup instead of an investigation. Watch for requirements that conflict, such as retention for legal hold versus a deletion request, and get legal and the data owner to resolve them in writing. Finally, make sure logging requirements name the data that must never be logged, because log files are one of the most common places secrets and personal data leak.'},
    {'id': 'secure-architecture-design', 'title': 'Secure Architecture and Design: Threat Modeling and Patterns', 'summary': 'Threat modeling methods, attack surface reduction, zero trust and the security design of APIs, microservices, cloud, containers and AI-enabled systems.', 'diagram': 'cswDfd', 'vocabIds': ['f47', 'f49', 'f52', 'f54', 'f57', 'f59', 'f62', 'f64'], 'quizIds': ['q29', 'q32', 'q36', 'tf13', 'msq8'], 'reading': 'Design is the cheapest and most powerful place to remove vulnerabilities, because a flaw in the architecture cannot be patched away by coding carefully. The central design activity is threat modeling: a structured way to ask what we are building, what can go wrong, what we will do about it, and whether we did a good job. Most methods start from a data flow diagram, which shows processes, data stores, external entities and the flows between them, plus trust boundaries where data moves between zones of different trust. The flows that cross a trust boundary are where you look first.\n\nYou need to distinguish the main methods. STRIDE classifies threats as Spoofing, Tampering, Repudiation, Information disclosure, Denial of service and Elevation of privilege, and each maps to a security property: authentication, integrity, non-repudiation, confidentiality, availability and authorization. DREAD ranks threats by scoring Damage, Reproducibility, Exploitability, Affected users and Discoverability. STRIDE classifies, DREAD prioritizes. PASTA, the Process for Attack Simulation and Threat Analysis, is a seven-stage risk-centric method that starts from business objectives and uses attack simulation.\n\nArchitecture then applies design principles at scale. Attack surface reduction removes features, ports and accounts nobody needs. Zero trust, described in NIST SP 800-207, abandons trust based on network location: every request is authenticated, authorized and evaluated using identity, device state and context, with a policy decision point and policy enforcement points. In microservices, services authenticate each other, often with mutual TLS, and every service authorizes its callers, because an attacker who gets inside the network could otherwise call any service. APIs must authenticate callers, authorize at the object and function level, validate input against a schema, limit rates and avoid over-sharing data. Broken object level authorization, where changing an identifier reaches another user\'s data, is the leading API risk.\n\nCloud, container and serverless designs change who is responsible for what. Under the shared responsibility model the provider secures the infrastructure and the customer is always responsible for its own data, identities, configuration and code, with the split shifting by service model. Containers share the host kernel and so isolate less strongly than virtual machines: use minimal scanned images, run as non-root, keep secrets out of images and apply network policies. Identity architecture uses federation: SAML or OpenID Connect carry authentication, while OAuth 2.0 is an authorization framework, a distinction exams love.\n\nTwo further design topics round this out. Cryptographic architecture means using vetted algorithms, protecting data in transit, at rest and where needed in use, and managing keys through their lifecycle in a dedicated key service or hardware module apart from the data. AI-enabled software adds threats such as prompt injection, training data poisoning, model theft and leakage of sensitive data through outputs. Treat model output as untrusted input, give any tools the model can call the least privilege, and require human approval for high-impact actions.', 'fundamentalsLabel': 'New to threat modeling? See the everyday analogy', 'fundamentals': 'Threat modeling a design is like a burglar-minded walk-through of a house plan before it is built. You mark where people legitimately come and go (flows), where the property line and the front door are (trust boundaries), then at each door and window ask how it could be forced, faked, hidden behind or overloaded (STRIDE). You rank which break-ins would hurt most (DREAD) or sketch the easiest route to the jewelry box (attack tree). Zero trust is like checking a visitor badge at every door inside the building, not just at the lobby. Zero trust means being in the lobby does not mean you can open the server-room door.', 'keyTerms': ['Threat model', 'STRIDE', 'DREAD', 'PASTA', 'Attack tree', 'Data flow diagram', 'Trust boundary', 'Zero trust', 'Mutual TLS'], 'commonTraps': ['STRIDE classifies threats and DREAD ranks them; options that swap the two are wrong.', 'OAuth 2.0 is an authorization framework; authentication of the user comes from OpenID Connect or SAML.', 'A gateway that authenticates users does not remove the need for each microservice to authorize its callers.', 'The customer always owns its data, identities and configuration in the cloud; misconfigured storage is a customer failure.', 'Obscurity, such as long random identifiers, does not replace an object-level authorization check.'], 'scenario': 'A retailer is designing an order API behind a gateway, with several microservices in containers talking to a payment service and a customer database. The team draws a data flow diagram, marks the gateway and the database as trust boundaries, and runs STRIDE on each flow. It finds that internal services trust any caller, orders can be fetched by changing an identifier, and database keys sit beside the data. The design is changed to use mutual TLS between services, object-level authorization in every service, a separate key service and narrowly scoped identities for each workload.', 'onTheJob': 'Do threat modeling in short, regular sessions with developers in the room, not as a heavyweight document written by security alone. Start with a whiteboard data flow diagram, spend most of the time at trust boundaries, and track every threat as a ticket with an owner so it is mitigated or explicitly accepted. Prefer removing a feature over hardening it, and prefer a standard pattern, such as an established identity provider, over a custom design. In cloud work, review identity and access policies as carefully as code, because over-broad roles are the most common root cause of serious incidents. When AI features appear in a design, ask what the model is allowed to do on behalf of a user and what happens if its output is hostile.'},
    {'id': 'secure-implementation', 'title': 'Secure Implementation: Coding Defenses and Safe Practices', 'summary': 'The coding practices that prevent injection, scripting, memory and access control flaws, plus secrets, cryptography, review and repository security.', 'diagram': 'cswValidate', 'vocabIds': ['f67', 'f69', 'f71', 'f73', 'f76', 'f78', 'f80', 'f82'], 'quizIds': ['q40', 'q43', 'q47', 'tf18', 'msq11'], 'reading': 'Implementation is where design intentions meet real code, and most exploited vulnerabilities come from a small set of recurring mistakes. The OWASP Top 10 lists the most critical web application risk categories for awareness. Broken access control has been first in both the 2021 and 2025 editions, followed in the 2025 list by security misconfiguration and software supply chain failures, with cryptographic failures, injection and insecure design also present.\n\nThe foundation of defending against injection and scripting attacks is to keep data and code separate. Input validation checks that data has the expected type, length, range and format, and it works best as an allow-list of what is acceptable, enforced on the server because client checks are trivially bypassed. SQL injection is prevented primarily by parameterized queries, which tell the database that input is always a value, never syntax. Cross-site scripting is prevented primarily by output encoding that matches the context, whether HTML body, attribute, JavaScript or URL, with a content security policy as a backstop. Cross-site request forgery abuses the browser attaching cookies automatically, and anti-forgery tokens and SameSite cookies stop it. Server-side request forgery makes your server fetch an attacker-chosen address, so you allow-list destinations and block internal ranges.\n\nAccess control must be enforced on the server, for every request, with default deny. Hiding a link or a button is not access control, and neither is a hard-to-guess identifier. Changing an identifier to reach another user record is an insecure direct object reference, and the fix is an ownership check on the object. Error handling follows the same logic: users see a generic message while detail goes to protected logs, because stack traces and queries reveal internals to attackers.\n\nMemory-related flaws dominate in languages such as C and C++. A buffer overflow writes past the end of a buffer, and use-after-free uses memory that has been released. Mitigations such as stack canaries, data execution prevention and address space layout randomization make exploitation harder, but only bounds checking, careful coding or a memory-safe language removes the bug.\n\nCryptography and secrets deserve their own discipline. Never invent algorithms: use vetted libraries, current algorithms and a cryptographically secure random number generator. Store passwords with a unique salt and a slow algorithm such as Argon2id, bcrypt, scrypt or PBKDF2, because passwords are checked, never recovered. Keep keys and secrets out of source code and images and hold them in a secrets manager with rotation and audit. A secret that was ever committed must be treated as compromised and rotated. Finally, protect the pipeline that carries code: secure code review combining human review and tools, hardening to a baseline such as a CIS Benchmark, and repository protections such as branch protection with independent review and signed commits.', 'fundamentalsLabel': 'New to secure coding? See the everyday analogy', 'fundamentals': 'Injection attacks are like a restaurant order slip where a customer is allowed to write in the notes field. If the kitchen treats everything on the slip as instructions, a customer who writes "and give me the cash from the register" gets it. Parameterized queries are a slip with a fixed form: the notes box can only ever be read as a request for ingredients, never as an instruction to the staff. Output encoding is like printing the customer name on the receipt in a way that cannot be read as a command, and access control is the manager checking, at every request, that the person asking is allowed to ask.', 'keyTerms': ['Allow-list validation', 'Parameterized query', 'Output encoding', 'XSS', 'CSRF', 'SSRF', 'Buffer overflow', 'TOCTOU', 'Password hashing'], 'commonTraps': ['Client-side validation is a usability feature; the server must enforce validation and authorization.', 'ASLR and similar mitigations make memory exploits harder but do not remove the bug; fixing the code or changing language does.', 'Passwords are hashed with a unique salt and a slow algorithm, not encrypted; there is no reason to recover them.', 'XSS abuses a site trust in the content it serves; CSRF abuses a site trust in the requests a browser sends.', 'A secret removed from the latest commit is still exposed in history and clones, so it must be rotated.'], 'scenario': 'A security review of an internal portal finds a search page that concatenates user input into SQL, a comments page that echoes input into HTML, an export endpoint that accepts any record number, and an API key in a repository from a year ago. The remediation is to switch to parameterized queries, apply context-aware output encoding, add an ownership check to the export, rotate the key and add secret scanning to the pipeline. Each fix removes a root cause rather than filtering symptoms.', 'onTheJob': 'Make the safe way the easy way. Provide teams with vetted libraries and framework defaults for output encoding, query building, authentication and cryptography, then review deviations, instead of expecting every developer to remember every rule. Put secret scanning and dependency checks in pre-commit and in the pipeline so mistakes are caught in minutes. In code review, focus effort on authentication, authorization, input parsing, cryptography and anything touching money or personal data. Avoid the temptation to block-list: attackers find the encoding or variant you did not list, so prefer allow-lists and structural defenses such as parameterization.'},
    {'id': 'secure-software-testing', 'title': 'Secure Software Testing: Tools, Techniques and Release Criteria', 'summary': 'Static, dynamic and interactive testing, fuzzing, penetration testing, test data, and how test results feed release decisions.', 'diagram': 'cswTestTools', 'vocabIds': ['f85', 'f87', 'f89', 'f91', 'f93', 'f95', 'f97', 'f99'], 'quizIds': ['q51', 'q54', 'q58', 'tf23', 'msq13'], 'reading': 'Security testing answers a different question from functional testing. Functional tests ask whether the software does what it should, while security tests ask whether it refuses to do what it should not do. A security test plan therefore derives its cases from security requirements, abuse cases and the threat model, not just from the feature list. Negative testing, which supplies invalid, unexpected or hostile input and actions, is central: boundary values, wrong data types, tampered tokens, repeated guesses and attempts to skip steps.\n\nThe automated tool families are distinguished by what they can see. Static application security testing (SAST) analyzes source code, bytecode or binaries without running the application. It can start as soon as code exists and points to the exact line, but it can produce false positives and cannot see runtime or configuration problems. Dynamic application security testing (DAST) attacks a running application from the outside with no need for source code. It finds runtime and configuration issues, but cannot identify the line and covers only the paths it reaches. Interactive application security testing (IAST) places sensors inside the running application while tests exercise it, which gives accurate findings tied to code, but only for the paths the tests reach. Runtime application self-protection (RASP) is not primarily a test: it sits inside the application and blocks attacks in production.\n\nFuzz testing deserves special mention. A fuzzer feeds large volumes of malformed or random input to a program to provoke crashes, hangs and memory errors, and coverage-guided fuzzers evolve inputs to reach new code. It is the best technique for unknown input-handling and memory-safety flaws, especially in parsers and protocol handlers. Penetration testing is a different kind of activity: an authorized, scoped, time-boxed attempt to exploit weaknesses, often chained together, to show real impact. It needs written authorization and rules of engagement before it starts. A vulnerability scan is automated, broad and repeatable but only lists potential weaknesses, whereas a penetration test proves exploitability.\n\nGood test practice supports everything above. Code coverage shows what code ran during tests but not whether the assertions were meaningful. Regression tests rerun existing checks after every change, and each fixed vulnerability should get its own regression test so it cannot silently return. Test data must not be production personal data: use synthetic data or data that has been masked or anonymized, because test systems are usually less protected.\n\nTesting ends in a decision. Exit criteria, such as no open critical or high vulnerabilities and all required scans completed, define when software may be released. If the business wants to release with an open finding, the correct path is documented risk acceptance by the accountable owner with compensating controls and a remediation date. It is not a quiet exception by the project team, a reclassification of severity or the omission of the finding from the report.', 'fundamentalsLabel': 'New to security testing? See the everyday analogy', 'fundamentals': 'Think of testing a new car. Reading the engineering drawings for mistakes is static analysis, because nothing is moving yet. Driving it around a track and trying to break it is dynamic testing. Putting sensors inside the engine while someone drives is interactive testing. Slamming the controls with random, absurd inputs to see what fails is fuzzing, and hiring a professional thief with written permission to actually steal it is a penetration test. The final inspection checklist that must all be green before the car leaves the factory is the exit criteria.', 'keyTerms': ['SAST', 'DAST', 'IAST', 'RASP', 'Fuzzing', 'Penetration test', 'Rules of engagement', 'Negative testing', 'Regression test'], 'commonTraps': ['SAST needs code and can name the line; DAST needs only a running application and cannot; the two are often reversed in distractors.', 'A vulnerability scan lists possible weaknesses while a penetration test actually exploits them.', 'Penetration testing requires written authorization and rules of engagement first, never just a verbal agreement.', 'Real production personal data does not belong in test environments, even on an internal network.', 'Releasing with an open critical finding needs documented risk acceptance from the accountable owner, not a project-level exception.'], 'scenario': 'A team is about to release a service that parses uploaded documents. Static analysis runs on every commit, dependency scanning runs in the pipeline, and a coverage-guided fuzzer has been running against the document parser for a week and found two crashes, both fixed with regression tests. A dynamic scan runs against staging, and an outside firm performs a penetration test under written rules of engagement. One medium finding remains, and the product owner signs a risk acceptance with a remediation date.', 'onTheJob': 'Do not drown developers in raw scanner output. Triage first, deduplicate, rank by exploitability and exposure, and send actionable tickets with the line of code and a suggested fix. Run quick checks on every commit and slower deep scans nightly or per release. Treat fuzzing as continuous infrastructure for anything that parses untrusted data, because it keeps finding bugs as the code changes. Before a penetration test, agree on scope, hours, contacts and what to do if something breaks, and give testers realistic accounts and architecture documentation so they spend time on depth instead of discovery. Keep the release criteria written down so decisions on the deadline day are not improvised.'},
    {'id': 'secure-deployment-operations', 'title': 'Secure Deployment, Operations and Maintenance', 'summary': 'Release and configuration management, pipeline security, vulnerability and patch management, incident response for software, and end of life.', 'diagram': None, 'vocabIds': ['f102', 'f103', 'f105', 'f107', 'f109', 'f110', 'f112', 'f114'], 'quizIds': ['q62', 'q64', 'q67', 'tf28', 'msq16'], 'reading': 'Software is not finished at release, and a large part of its security is decided in how it is built, shipped, run and eventually retired. Release management controls how a build moves into production through approvals, versioning, tested packages and rollback plans, and code signing lets recipients verify the publisher and that the artifact has not been altered. Remember what a signature does not prove: it does not show that the code is free of vulnerabilities, and if the build itself is compromised the malicious output will be signed too. Configuration management identifies each configuration item, defines an approved baseline and detects drift from it.\n\nThe delivery pipeline has become a prime target, because whatever it builds gets trusted. Protect it with short-lived, narrowly scoped credentials, isolated and ephemeral build runners, protected secrets, signed artifacts, reviewed changes to the pipeline definition and logging of all of the above. The SolarWinds compromise inserted malicious code during the build, not in the source repository, which is why build integrity matters. Before go-live an operational readiness review confirms secure defaults, hardening, monitoring, tested recovery and a signed security acceptance.\n\nOnce running, vulnerability management is a continuous cycle: discover, assess and prioritize, remediate or mitigate, verify and report. Prioritization uses CVSS severity together with context, such as whether the system is internet-facing, whether exploit code exists and whether the flaw appears in the CISA known exploited vulnerabilities catalog or has a high EPSS score. A CVSS base score measures intrinsic severity, not the risk to you. Patch management, described in NIST SP 800-40, tests and deploys updates on a risk-based schedule with an expedited path for actively exploited flaws, and uses compensating controls such as virtual patching or restricted access when a patch cannot yet be applied.\n\nSoftware incident response follows the familiar sequence: prepare, detect and analyze, contain, eradicate and recover, then review lessons learned. Product teams also need a way to receive vulnerability reports, usually through a product security incident response team and a published contact, and they practice coordinated disclosure with the reporter, agreeing a timeline so a fix exists before details become public. After any serious event, root cause analysis fixes the class of problem and updates requirements, tests and training.\n\nFinally, software has an end. When a vendor stops issuing patches the product is at end of life, and continuing to run it means living with flaws that can never be fixed. Retirement should be planned: notify users, migrate or archive data under retention rules, remove accounts, credentials and network access, and sanitize media following NIST SP 800-88 using clear, purge or destroy as appropriate, since deleting files or quick formatting leaves recoverable data.', 'fundamentalsLabel': 'New to deployment and operations? See the everyday analogy', 'fundamentals': 'Running software in production is like running a restaurant after the grand opening. The recipe card that cooks must follow is the configuration baseline, and a change to it goes through the head chef (change control). Trying a new dish on a few tables first is a canary release. A recall notice when a supplier ingredient turns out to be unsafe is a vulnerability disclosure, and deciding which fridges to check first, the ones with the suspect batch that serve the most customers, is prioritization. When the restaurant finally closes you do not simply lock the door: you empty the storage, shred the order books and cancel the supplier accounts, which is decommissioning.', 'keyTerms': ['Release management', 'Code signing', 'Configuration baseline', 'Canary release', 'CI/CD pipeline', 'Infrastructure as code', 'CVSS', 'Patch management', 'Coordinated disclosure'], 'commonTraps': ['A digital signature proves publisher and integrity, not that the software is free of vulnerabilities.', 'CVSS base score is severity, not risk; exposure and active exploitation can make a lower score more urgent.', 'Emergency patches still follow an expedited, recorded process, and unsupported end-of-life software needs migration plus compensating controls.', 'Deleting files, emptying the recycle bin or a quick format is not sanitization.', 'Preserve evidence and contain before cleaning up during incident response; lessons learned feed back into requirements and tests.'], 'scenario': 'A critical flaw is announced in a library used by a company internet-facing service, and the exploit is already seen in the wild. The team queries its inventory to find affected products, ranks the internet-facing one first, applies a virtual patch at the web application firewall within hours, tests and deploys the vendor fix through a canary release the next day, and records a short post-incident review. Months later it retires an old report server by migrating its data, removing its accounts and purging its disks under NIST SP 800-88.', 'onTheJob': 'Know what you run. Keep an accurate inventory of applications, versions and dependencies, because every other process depends on it, and a vulnerability announcement with no inventory means days of guesswork. Agree service-level targets for fixing flaws by severity and exposure, and review exceptions regularly. Treat the pipeline like production: separate its credentials, review its definitions and watch its logs. Rehearse recovery and incident response with tabletop exercises, including how to reach the reporter of a vulnerability. Put end-of-life dates on a calendar at purchase time, so retirement is planned and funded long before support stops.'},
    {'id': 'secure-supply-chain', 'title': 'Secure Software Supply Chain: Components, Suppliers and Assurance', 'summary': 'Third-party and open-source risk, SBOMs and VEX, supply chain attacks and defenses, licensing, supplier contracts and assurance schemes.', 'diagram': 'cswSbom', 'vocabIds': ['f116', 'f117', 'f119', 'f120', 'f122', 'f124', 'f125', 'f127'], 'quizIds': ['q70', 'q72', 'q75', 'tf32', 'msq18'], 'reading': 'Modern applications are mostly assembled, not written. A typical product includes hundreds of open-source libraries, a build system, container images and cloud services, all supplied by others. A software supply chain attack compromises something that a victim already trusts, such as a dependency, a build server, an update channel or a vendor, so that malicious or vulnerable code arrives through a legitimate path. SolarWinds in 2020 showed tampering inside a vendor build that was then delivered as a signed update. Log4Shell in 2021 showed a single flaw in a ubiquitous logging library affecting thousands of products at once.\n\nThe first defense is knowing what you have. A software bill of materials (SBOM) is a machine-readable inventory of the components in a product, with names, versions and suppliers, and it lets you find affected products quickly when a new vulnerability is announced. The main formats are SPDX and CycloneDX, and the NTIA minimum elements define the baseline data. An SBOM is an inventory, not an assessment: it does not say whether a component is exploitable in your product. A Vulnerability Exploitability eXchange (VEX) statement is the supplier assertion that a known vulnerability does or does not affect a product, for example because the vulnerable function is never reached. Software composition analysis (SCA) tools find open-source components in a codebase, report vulnerabilities and licenses, and can generate SBOMs, and they should run continuously because new vulnerabilities are disclosed for components already shipped.\n\nSeveral specific attacks are named on the exam. Dependency confusion publishes a public package with the same name as an internal one and a higher version so build tools fetch the attacker copy. Typosquatting relies on package names that resemble popular ones. Defenses include reserving or scoping internal names and resolving them only from a private registry, pinning versions with lock files, verifying hashes, reviewing updates for critical dependencies and limiting build network access. Build integrity frameworks such as SLSA define increasingly strong requirements for provenance, which is a verifiable record of the source, process and builder that produced an artifact.\n\nLicensing is also supply chain risk. Permissive licenses such as MIT, BSD and Apache 2.0 allow broad reuse, while copyleft licenses such as the GPL require derivative works to be distributed under the same terms, and the AGPL extends that to software offered over a network.\n\nSuppliers are managed through due diligence and contracts. Assess a supplier\'s security practices, vulnerability history, maintenance activity and independent reports such as SOC 2, then continue monitoring after selection for new vulnerabilities, ownership changes and end of support. Contracts make assurance enforceable: security requirements, breach notification, the right to audit, vulnerability handling timelines and exit terms. For product assurance, Common Criteria (ISO/IEC 15408) evaluates a product against a Security Target and reports an evaluation assurance level from EAL1 to EAL7. A higher level reflects a more rigorous evaluation, not more features and not a guarantee of security.', 'fundamentalsLabel': 'New to supply chain security? See the everyday analogy', 'fundamentals': 'Think of a food manufacturer. Every ingredient comes from a supplier, who gets theirs from another supplier. A recall can start three links away. The ingredient list on the package is the SBOM, and the note saying the recalled flour is not in the product you bought is the VEX. Checking suppliers before signing, putting inspection rights into the contract and testing deliveries continuously are the controls. A rogue supplier shipping a look-alike flour in the same sack is a dependency confusion or typosquatting attack, and a tamper-evident seal and a record of which plant made each batch is provenance.', 'keyTerms': ['Supply chain attack', 'SBOM', 'SPDX', 'CycloneDX', 'VEX', 'SCA', 'Dependency confusion', 'SLSA', 'Provenance'], 'commonTraps': ['An SBOM lists components; it does not state whether they are vulnerable or exploitable, which is the job of vulnerability data and VEX.', 'SAST analyzes the code you wrote while SCA analyzes the open-source and third-party code you imported.', 'Dependency confusion exploits a higher version number across registries; typosquatting exploits a misspelled name.', 'A higher EAL means a more rigorous evaluation, not more security features or a guarantee of no vulnerabilities.', 'A questionnaire is evidence, but a contract term is what makes a supplier security commitment enforceable.'], 'scenario': 'A vendor announces a critical flaw in a widely used open-source library. The company queries its SBOM inventory and finds the library in four products. VEX statements from its own product teams show that two are not affected because the vulnerable function is never called, so remediation focuses on the other two. Afterward the team pins dependency versions, scopes internal package names to its private registry, adds SCA to every build and updates supplier contracts to require breach notification and an audit right.', 'onTheJob': 'Generate SBOMs automatically at build time and store them with each release, because a document written by hand at audit time will be wrong. Ask suppliers for SBOMs and VEX data as part of procurement, and treat a supplier that cannot provide them as a risk factor. Prefer fewer, well-maintained dependencies and review the health of critical ones: how many maintainers, how recent are releases, how quickly are issues fixed. Mirror critical packages in a private registry and block direct downloads from the public internet during builds. Keep a decision record for licenses, with legal review for any copyleft component that will be distributed.'},
]

MADLIBS = [
    {'id': 'ml-csslp-1', 'cat': 'csslpConcepts', 'scenario': 'A bank branch lets a teller open only the drawer assigned to them, which is the principle of {b1}. Withdrawals over a set limit also need a second employee to sign, which is {b2}. If the branch power fails, the vault stays locked, reflecting {b3}.', 'blanks': [{'key': 'b1', 'options': ['least privilege', 'complete mediation', 'open design'], 'correct': 0}, {'key': 'b2', 'options': ['defense in depth', 'separation of duties', 'psychological acceptability'], 'correct': 1}, {'key': 'b3', 'options': ['economy of mechanism', 'least common mechanism', 'fail-safe defaults'], 'correct': 2}], 'explanation': 'Least privilege limits each role to what it needs, separation of duties splits a sensitive process so one person cannot finish it alone, and fail-safe defaults means failure ends in a secure (denied) state.'},
    {'id': 'ml-csslp-2', 'cat': 'csslpLifecycle', 'scenario': 'A company wants to see which security activities other firms in its industry already perform, so it uses {b1}, a {b2} model. To plan its own improvement roadmap with measurable levels, it uses {b3}, which is {b4}.', 'blanks': [{'key': 'b1', 'options': ['STRIDE', 'SAMM', 'BSIMM'], 'correct': 2}, {'key': 'b2', 'options': ['quantitative-only', 'descriptive', 'prescriptive'], 'correct': 1}, {'key': 'b3', 'options': ['the Common Criteria', 'OWASP SAMM', 'CVSS'], 'correct': 1}, {'key': 'b4', 'options': ['descriptive', 'a vulnerability scoring scheme', 'prescriptive'], 'correct': 2}], 'explanation': 'BSIMM observes and reports what real programs do (descriptive), while SAMM prescribes practices and maturity levels to build a roadmap (prescriptive).'},
    {'id': 'ml-csslp-3', 'cat': 'csslpReq', 'scenario': 'A requirement states that after an outage the service must be running within two hours, which is the {b1}, and that no more than 15 minutes of transactions may be lost, which is the {b2}. The data owner assigns each field a sensitivity level through {b3}.', 'blanks': [{'key': 'b1', 'options': ['SLE', 'RPO', 'RTO'], 'correct': 2}, {'key': 'b2', 'options': ['ALE', 'RPO', 'RTO'], 'correct': 1}, {'key': 'b3', 'options': ['data classification', 'threat modeling', 'code review'], 'correct': 0}], 'explanation': 'RTO is the time allowed to restore service and RPO is the amount of data loss allowed, measured in time. Data classification by the owner then drives the controls for each field.'},
    {'id': 'ml-csslp-4', 'cat': 'csslpDesign', 'scenario': 'During threat modeling a team walks each element of a data flow diagram through six categories, using {b1}. To rank the resulting threats by damage potential, reproducibility, exploitability, affected users and discoverability they use {b2}. They look first at flows that cross a {b3}.', 'blanks': [{'key': 'b1', 'options': ['PASTA', 'DREAD', 'STRIDE'], 'correct': 2}, {'key': 'b2', 'options': ['STRIDE', 'DREAD', 'an attack tree'], 'correct': 1}, {'key': 'b3', 'options': ['cache layer', 'logging pipeline', 'trust boundary'], 'correct': 2}], 'explanation': 'STRIDE classifies threats, DREAD scores and ranks them, and threats concentrate where data crosses a trust boundary between zones of different trust.'},
    {'id': 'ml-csslp-5', 'cat': 'csslpImpl', 'scenario': 'To stop SQL injection a developer uses {b1}; to stop cross-site scripting the developer applies context-aware {b2}; and because client-side checks can be bypassed, validation is enforced on the {b3}.', 'blanks': [{'key': 'b1', 'options': ['longer URLs', 'parameterized queries', 'quote stripping'], 'correct': 1}, {'key': 'b2', 'options': ['session timeouts', 'output encoding', 'input length limits'], 'correct': 1}, {'key': 'b3', 'options': ['load balancer', 'browser', 'server'], 'correct': 2}], 'explanation': 'Parameterized queries keep data from being read as SQL, output encoding keeps data from being read as script, and the server must enforce validation because attackers can skip the client entirely.'},
    {'id': 'ml-csslp-6', 'cat': 'csslpSupply', 'scenario': 'A new vulnerability is announced in a library, so the team checks its {b1} to see which products contain it. The supplier then publishes a {b2} statement saying the vulnerable function is never called. An attacker who publishes a public package with an internal package name and a higher version is carrying out {b3}.', 'blanks': [{'key': 'b1', 'options': ['threat model', 'penetration test report', 'SBOM'], 'correct': 2}, {'key': 'b2', 'options': ['Protection Profile', 'escrow', 'VEX'], 'correct': 2}, {'key': 'b3', 'options': ['session fixation', 'dependency confusion', 'cross-site scripting'], 'correct': 1}], 'explanation': 'An SBOM inventories components, a VEX statement says whether a known vulnerability actually affects the product, and dependency confusion tricks a build into fetching an attacker package with a higher version.'},
]

SEQUENCES = [
    {'id': 'seq-csslp-1', 'cat': 'csslpDesign', 'prompt': 'Put the steps of a basic threat modeling session in the order in which they are normally performed.', 'steps': ['Define the scope and draw a data flow diagram with trust boundaries', 'Identify threats on each element, for example by applying STRIDE', 'Rate and prioritize the threats, for example with DREAD or risk analysis', 'Choose mitigations and assign them as tracked work items', 'Validate that the mitigations work and update the model when the design changes'], 'explanation': 'You must know what you are building before you can find threats. Prioritization precedes choosing mitigations so effort goes where risk is greatest, and the model is kept current because designs change.'},
    {'id': 'seq-csslp-2', 'cat': 'csslpLifecycle', 'prompt': 'Order the four groups of the NIST Secure Software Development Framework as they naturally build on each other.', 'steps': ['Prepare the Organization (people, processes and tools are ready)', 'Protect the Software (guard code and build assets from tampering)', 'Produce Well-Secured Software (design, code, review and test with security in mind)', 'Respond to Vulnerabilities (identify, fix and learn from residual flaws)'], 'explanation': 'The SSDF is usually remembered as prepare, protect, produce, respond: organizational readiness first, then protection of the environment, then secure production of the software, and finally handling the vulnerabilities that remain after release.'},
    {'id': 'seq-csslp-3', 'cat': 'csslpDeploy', 'prompt': 'Order the phases of software incident response.', 'steps': ['Preparation (policies, tools, contacts and training in place)', 'Detection and analysis (confirm and scope the incident)', 'Containment (stop the spread and preserve evidence)', 'Eradication and recovery (remove the cause and restore service)', 'Post-incident review (lessons learned feed requirements, tests and training)'], 'explanation': 'Preparation comes first so the team can act fast, detection confirms what happened, containment limits damage before cleanup begins, and the review closes the loop by improving the earlier lifecycle phases.'},
    {'id': 'seq-csslp-4', 'cat': 'csslpDeploy', 'prompt': 'A critical vulnerability is reported in a shipped product by an outside researcher. Order the vulnerability handling steps.', 'steps': ['Acknowledge the report and validate the issue', 'Assess severity and affected versions and decide priority', 'Develop and test a fix', 'Release the fix and publish an advisory, coordinated with the reporter', 'Verify deployment, monitor and record lessons learned'], 'explanation': 'Coordinated disclosure means the fix exists and the timing is agreed with the reporter before details are published, and verification afterward confirms that customers are actually protected.'},
    {'id': 'seq-csslp-5', 'cat': 'csslpSupply', 'prompt': 'Order the steps for responsibly adopting a new open-source component.', 'steps': ['Identify the need and shortlist candidate components', 'Assess maintenance health, vulnerability history and license', 'Approve and pin the exact version in the private registry or lock file', 'Record the component in the SBOM and scan it with software composition analysis', 'Monitor continuously for new vulnerabilities, changes and end of support'], 'explanation': 'Assessment comes before adoption so risky or incompatible components never enter the code. Pinning and recording make the choice reproducible and findable, and monitoring continues for the life of the dependency.'},
]

CASE_STUDIES = [
    {'id': 'cs-csslp-harborview-health', 'cat': 'csslpDesign', 'title': 'HarborView Health Patient Portal', 'scenario': "HarborView Health is building a patient portal as a set of containerized microservices behind an API gateway. Patients view lab results and message clinicians, and the service stores diagnoses and appointment history for people in several countries. The architect's first design has the gateway authenticate users with an identity provider, after which internal services trust any request that arrives from the cluster network. Results are fetched with a URL such as /results/48213, where the number is the record identifier. Encryption keys for the database are kept in a configuration table in the same database. The team plans a single penetration test just before launch and has not yet produced a threat model or a privacy assessment. The product owner wants to add an AI assistant that summarizes lab results and can book appointments on a patient's behalf by calling internal services. Delivery is in two-week sprints, and legal has confirmed that health privacy laws apply to the data.", 'questions': [{'id': 'cs-csslp-harborview-health-q1', 'type': 'mc', 'question': 'Which weakness in the first design is the MOST serious from a design standpoint?', 'options': ['The gateway uses an identity provider rather than a locally built login system', 'The portal is deployed as containers instead of virtual machines', 'The team uses two-week sprints for delivery', 'Internal services trust any request from the cluster network, so one foothold exposes every service'], 'correct': 3, 'explanation': 'Services that trust any caller on the network allow lateral movement after a single compromise, so each service needs authenticated callers (for example with mutual TLS) and its own authorization. Using an identity provider is good practice, containers are acceptable with proper hardening, and sprint length is not a security design issue.'}, {'id': 'cs-csslp-harborview-health-q2', 'type': 'mc', 'question': 'A tester changes 48213 to 48214 in the results URL and sees another patient record. What control is missing?', 'options': ['Encryption of the database column that holds the lab results', 'A web application firewall rule that blocks numeric identifiers', 'A longer and more random record identifier format', 'An object-level authorization check that confirms the caller owns the requested record'], 'correct': 3, 'explanation': 'This is broken object-level authorization: the API authenticates the caller but never checks ownership of the object. Random identifiers only make guessing harder, a firewall rule cannot know who owns a record, and database encryption does not stop the application from returning the data to an unauthorized caller.'}, {'id': 'cs-csslp-harborview-health-q3', 'type': 'ms', 'question': 'Which TWO actions should happen EARLY, before more design and coding work is done? (Choose two.)', 'options': ['Move the encryption keys into the application configuration file', 'Wait for the pre-launch penetration test to show what the threats are', 'Run a threat model on the data flows, focusing on trust boundaries', 'Add a fixed tracking identifier to every user for marketing analytics', 'Perform a data protection impact assessment of how patient data is collected and shared'], 'correct': [2, 4], 'explanation': 'Threat modeling and a privacy impact assessment shape the architecture while changes are cheap. Waiting for a penetration test discovers design flaws late, and the other options either weaken key handling or add privacy exposure.'}, {'id': 'cs-csslp-harborview-health-q4', 'type': 'mc', 'question': 'For the AI assistant that can book appointments by calling internal services, which design control is the BEST?', 'options': ['Log the assistant prompts and responses and review them after the next release', 'Allow the assistant full access to every internal service so it can handle any request', 'Trust the model to refuse malicious instructions without further checks', 'Give the assistant the least privilege needed, treat its output as untrusted input and require patient confirmation before actions'], 'correct': 3, 'explanation': 'AI components can be manipulated by prompt injection, so their capabilities are limited to what is needed, their output is validated like any untrusted input, and consequential actions need explicit approval. Full access, blind trust and after-the-fact log review do not prevent harm at the time of the action.'}]},
    {'id': 'cs-csslp-northwind-pipeline', 'cat': 'csslpSupply', 'title': 'Northwind Logistics Build Pipeline Review', 'scenario': 'Northwind Logistics ships a customer-facing shipment tracking application and a mobile client. After a widely reported library vulnerability, leadership asks the security team to review the delivery process. The review finds that builds run on long-lived shared runners using one administrator credential for every pipeline. Dependencies are fetched from public registries without version pinning, and the team also publishes several internal packages whose names are not reserved on the public registry. No inventory of third-party components exists, so it took six days to find which products used the vulnerable library. Release packages are not signed. A third-party route optimization component is supplied by a small vendor under a contract that has no security clauses, and the vendor holds the only copy of the source code. Northwind also copied its production shipment database into the staging environment for realistic testing. The CISO wants a prioritized plan that improves supply chain security without halting delivery.', 'questions': [{'id': 'cs-csslp-northwind-pipeline-q1', 'type': 'mc', 'question': 'Which finding should be addressed FIRST to reduce the chance that a malicious package reaches production builds?', 'options': ['Pin dependency versions with hash verification and reserve or scope internal package names to a private registry', 'Ask developers to review every library by hand once a year', 'Increase the number of runners so builds finish faster', 'Move the mobile client to a different development framework'], 'correct': 0, 'explanation': 'Unpinned public fetches and unreserved internal names enable dependency confusion and malicious updates, and pinning with hashes plus controlled resolution closes that path. Changing frameworks, annual manual reviews and more runners do not stop a malicious package from being fetched.'}, {'id': 'cs-csslp-northwind-pipeline-q2', 'type': 'mc', 'question': 'The team could not tell which products used the vulnerable library for six days. What is the BEST control to fix this?', 'options': ['Generate an SBOM for every build and keep a searchable inventory, with software composition analysis', 'Add a note to the release process that developers should remember which libraries they use', 'Retain the penetration test reports from previous years', 'Block all open-source libraries from future builds'], 'correct': 0, 'explanation': 'An SBOM produced automatically at build time, combined with SCA, answers where a component is used within minutes. Relying on memory is unreliable, banning all open-source is impractical, and old penetration test reports do not list dependencies.'}, {'id': 'cs-csslp-northwind-pipeline-q3', 'type': 'ms', 'question': 'Which TWO changes best reduce the risk from the shared administrator credential and unsigned packages? (Choose two.)', 'options': ['Issue short-lived, narrowly scoped credentials to isolated, ephemeral build runners', 'Send release packages by email to customers instead of publishing them', 'Keep the shared credential but rename it so that it is less obvious', 'Disable pipeline logging to remove sensitive values from records', 'Digitally sign release artifacts and verify the signatures before installation'], 'correct': [0, 4], 'explanation': 'Scoped temporary credentials limit what a compromised build can do, and signing lets recipients verify origin and integrity. Renaming a credential is obscurity, emailing packages adds risk, and disabling logging destroys evidence.'}, {'id': 'cs-csslp-northwind-pipeline-q4', 'type': 'mc', 'question': 'Which action best addresses the risk of depending on the small vendor that holds the only copy of the route optimization source code?', 'options': ['Remove the component and write a replacement within the current sprint', 'Ask the vendor to send an informal security assurance by email', 'Negotiate security clauses and a software escrow arrangement, with the deposit verified to build', 'Accept the situation because the vendor has not had a problem so far'], 'correct': 2, 'explanation': 'Contract terms make security duties enforceable, and a verified escrow deposit preserves the ability to maintain the component if the vendor fails. Informal assurances are not enforceable, doing nothing leaves the risk open and an immediate rewrite is rarely realistic.'}, {'id': 'cs-csslp-northwind-pipeline-q5', 'type': 'tf', 'question': 'Copying the production shipment database into staging is acceptable as long as the staging environment is only reachable from the internal network.', 'answer': False, 'explanation': 'Test environments usually have weaker controls, so real customer data should be replaced by synthetic data or masked and anonymized before use. An internal network does not remove the breach and compliance exposure.'}]},
]

COMPARE = [
    {'id': 'cmp-csslp-1', 'cat': 'csslpConcepts', 'scenario': 'A finance application checks a user entitlements when a session starts and keeps them for eight hours for performance. Which improvement is the better recommendation?', 'optionA': 'Shorten the session timeout from eight hours to four hours so cached entitlements go stale more quickly.', 'optionB': 'Check authorization on every request, using a fast cached policy that is invalidated when permissions change.', 'better': 'B', 'why': 'Checking each request with an invalidating cache delivers complete mediation and still performs well. Shortening the timeout is the tempting runner-up but only narrows the window in which a revoked permission still works; it does not remove it.'},
    {'id': 'cmp-csslp-2', 'cat': 'csslpLifecycle', 'scenario': 'A team releases several times a day and the security manager needs a control to stop a critical dependency flaw from reaching production. Which is the better answer?', 'optionA': 'An automated pipeline gate that fails the build on critical findings unless a documented exception is approved.', 'optionB': 'A weekly manual review meeting where the team looks at the dependency report before the next release.', 'better': 'A', 'why': 'The automated gate runs on every build and enforces the criterion at the speed of delivery, with an accountable exception path. The weekly meeting looks thorough but cannot keep pace with several releases a day, so flawed builds ship between meetings.'},
    {'id': 'cmp-csslp-3', 'cat': 'csslpReq', 'scenario': 'A product manager wants the sign-up form to collect birth date and home address, although the product never uses them. What should the security architect recommend?', 'optionA': 'Drop those fields from the form and do not collect the data.', 'optionB': 'Collect the fields and encrypt them at rest with a strong algorithm and managed keys.', 'better': 'A', 'why': 'Data minimization removes the risk entirely, since data never collected cannot be breached or misused. Encrypting the fields is the tempting runner-up, but it keeps unnecessary data in scope for breach, compliance and retention obligations.'},
    {'id': 'cmp-csslp-4', 'cat': 'csslpReq', 'scenario': 'A team must prove to an auditor that every security requirement was implemented and tested. Which artifact is better?', 'optionA': 'The latest penetration test report showing the number of findings by severity.', 'optionB': 'A traceability matrix linking each requirement to design elements, code and test cases.', 'better': 'B', 'why': 'Traceability shows coverage requirement by requirement, including gaps. The penetration test report is the tempting runner-up because testing sounds like proof, but it shows what was found, not that each stated requirement was built and verified.'},
    {'id': 'cmp-csslp-5', 'cat': 'csslpDesign', 'scenario': 'A company wants a design for internal microservices that remains safe if an attacker gets a foothold on the network. Which is the better choice?', 'optionA': 'A stronger perimeter firewall and an authenticated gateway in front of all the services.', 'optionB': 'Mutual TLS between services plus authorization checks inside each service.', 'better': 'B', 'why': 'Service-to-service authentication and local authorization protect against lateral movement after a foothold. The gateway design is the tempting runner-up, but once an attacker is inside the network nothing stops direct calls to services that trust any internal caller.'},
    {'id': 'cmp-csslp-6', 'cat': 'csslpDesign', 'scenario': 'A team needs to prioritize a list of already identified threats in a design. Which technique is the better fit?', 'optionA': 'DREAD scoring of damage, reproducibility, exploitability, affected users and discoverability.', 'optionB': 'STRIDE classification of each threat into spoofing, tampering and the other categories.', 'better': 'A', 'why': 'DREAD produces a ranking so effort can be ordered. STRIDE is the tempting runner-up because it is the best known method, but it classifies threats rather than ranking them, so it does not tell the team which to fix first.'},
    {'id': 'cmp-csslp-7', 'cat': 'csslpImpl', 'scenario': 'A developer must protect against SQL injection in a legacy report that builds queries from user text. Which is the better fix?', 'optionA': 'Add a filter that removes quotes and semicolons from the input.', 'optionB': 'Rewrite the queries to use parameterized statements.', 'better': 'B', 'why': 'Parameterization addresses the root cause by keeping data separate from SQL syntax. The filter is the tempting runner-up because it is quick, but block-lists miss encodings and variants and leave the query structure injectable.'},
    {'id': 'cmp-csslp-8', 'cat': 'csslpTest', 'scenario': 'A vendor delivers a compiled web application with no source code and the customer wants to find vulnerabilities before go-live. Which approach is better?', 'optionA': 'A static analysis scan of the vendor repository, which the customer requests through the vendor.', 'optionB': 'A dynamic scan and a scoped penetration test against the running application in staging.', 'better': 'B', 'why': 'Dynamic testing needs only a running application, which is what the customer has. Static analysis is the tempting runner-up because it gives line-level findings, but it depends on source the customer does not hold and may never receive.'},
    {'id': 'cmp-csslp-9', 'cat': 'csslpDeploy', 'scenario': 'A critical vulnerability is being actively exploited in an internet-facing service, and the vendor patch needs two weeks of regression testing. Which is the better interim step?', 'optionA': 'Deploy the vendor patch to production immediately without regression testing to close the gap.', 'optionB': 'Apply a virtual patch or access restriction now and deploy the vendor fix after testing.', 'better': 'B', 'why': 'Compensating controls reduce exposure immediately while preserving stability. Deploying untested is the tempting runner-up because it feels decisive, but it can break production, and the exposure can usually be reduced faster by a targeted control.'},
    {'id': 'cmp-csslp-10', 'cat': 'csslpSupply', 'scenario': 'A company depends on a small vendor for a critical custom application and worries about the vendor failing. Which is the better assurance?', 'optionA': 'A clause obliging the vendor to fix defects within thirty days of notice.', 'optionB': 'A software escrow agreement with periodic verification that the deposit builds.', 'better': 'B', 'why': 'Escrow gives the customer the means to maintain the application if the vendor disappears. The defect-fix clause is the tempting runner-up, but a vendor that has failed cannot perform it, so it gives no continuity protection in that scenario.'},
]

CHEAT_SHEET = [
    {'heading': 'Exam facts and domain weights (verify at isc2.org)', 'points': ['CSSLP: 125 questions (multiple choice and advanced item types), 3 hours, 700 out of 1000 to pass, computerized at Pearson VUE test centers.', 'Domain weights: Secure Software Concepts 12%, Lifecycle Management 11%, Requirements 13%, Architecture and Design 15%, Implementation 14%, Testing 14%, Deployment, Operations and Maintenance 11%, Supply Chain 10%.', 'Experience: four years cumulative paid work in one or more of the eight domains; a four-year degree in a related field or an approved credential can waive one year; pass the exam first and you become an Associate of ISC2 with five years to earn the experience.', 'The weights are percentages of the exam, so design, implementation and testing together are over 40% of the questions.']},
    {'heading': 'Secure design principles', 'points': ['Least privilege, separation of duties, defense in depth, fail-safe defaults (default deny), complete mediation, economy of mechanism, open design, least common mechanism, psychological acceptability, separation of privilege.', 'Complete mediation = check every access every time; fail-safe defaults = failure results in denial; open design = only keys are secret.', 'Fail secure protects data, fail safe protects life; software questions normally want fail secure.', 'CIA triad properties map to threats: spoofing breaks authentication, tampering breaks integrity, repudiation breaks non-repudiation, disclosure breaks confidentiality, denial of service breaks availability, elevation of privilege breaks authorization.']},
    {'heading': 'Lifecycle models and maturity', 'points': ['Microsoft SDL, NIST SSDF (SP 800-218) and OWASP SAMM are prescriptive; BSIMM is descriptive and used for peer comparison.', 'SSDF groups: Prepare the Organization, Protect the Software, Produce Well-Secured Software, Respond to Vulnerabilities.', 'SAMM: five business functions (governance, design, implementation, verification, operations), three practices each, three maturity levels.', 'Shift left: the earlier a defect is found, the cheaper it is to fix; in agile and DevOps automate checks and write security acceptance criteria.', 'Policy (mandatory, high level) > standard (mandatory, specific) > guideline (optional) > procedure (steps).']},
    {'heading': 'Requirements, privacy and compliance', 'points': ['Missing security requirements are elicited first from data classification, laws, policies, threat models and abuse cases; make them testable and trace them in an SRTM.', 'Data classification is set by the data owner; FIPS 199 uses the high-water mark of confidentiality, integrity and availability impact.', 'RTO is time to restore and RPO is tolerable data loss; do not reverse them.', 'Privacy: data minimization, purpose limitation, retention limits, impact assessment early; pseudonymized data is generally still personal data.', 'GDPR (EU personal data), HIPAA (US health), PCI DSS (payment cards, contractual standard), SOX (financial reporting controls).']},
    {'heading': 'Threat modeling, architecture and design', 'points': ['STRIDE classifies, DREAD ranks, PASTA is risk-centric with seven stages, attack trees start from an attacker goal, LINDDUN is for privacy threats; start analysis at trust boundaries on a data flow diagram.', 'Zero trust (NIST SP 800-207): no implicit trust by network location; authenticate, authorize and evaluate each request.', 'Microservices: mutual TLS plus authorization inside every service; APIs: object-level authorization first, plus rate limits and schema validation.', 'OAuth 2.0 = authorization; OpenID Connect and SAML = authentication and federation.', 'Cloud: customer always owns data, identities, configuration and code; containers share the host kernel; serverless needs per-function least privilege.']},
    {'heading': 'Secure implementation', 'points': ['Allow-list validation on the server; parameterized queries for SQL injection; context-aware output encoding for XSS; anti-forgery tokens and SameSite cookies for CSRF; allow-list destinations for SSRF.', 'Broken access control is first in the OWASP Top 10 (2021 and 2025); hiding a link is not access control; fix IDOR with object ownership checks.', 'Memory safety: bounds checking or memory-safe languages remove the bug; ASLR, DEP and canaries only make exploitation harder.', 'Passwords: unique salt plus Argon2id, bcrypt, scrypt or PBKDF2; never reversible encryption; never invent cryptography.', 'Committed secrets are compromised: revoke and rotate, then add a secrets manager and scanning.']},
    {'heading': 'Testing and assurance', 'points': ['SAST = source, early, names the line, false positives; DAST = running app, no source, runtime issues; IAST = in-app agent during tests; RASP = in-app protection in production.', 'Fuzzing finds unknown input-handling and memory flaws; penetration tests exploit and need written authorization and rules of engagement; scans list, pen tests prove.', 'Negative testing and abuse cases derive security test cases; add a regression test for every fixed vulnerability; coverage does not prove meaningful checks.', 'Never use raw production personal data in test; mask, anonymize or use synthetic data.', 'Releasing with an open critical finding needs documented risk acceptance by the accountable business owner.']},
    {'heading': 'Deployment, operations and supply chain', 'points': ['Sign release artifacts; protect the CI/CD pipeline with short-lived scoped credentials, ephemeral runners and reviewed pipeline changes; scan infrastructure as code before deployment.', 'CVSS is severity, not risk: weigh exposure and active exploitation (CISA known exploited vulnerabilities, EPSS); NIST SP 800-40 for patching; compensating controls when patching is delayed.', 'Incident response: prepare, detect and analyze, contain, eradicate and recover, post-incident review; coordinated vulnerability disclosure with the reporter.', 'End of life means no more patches: plan migration; sanitize media per NIST SP 800-88 (clear, purge, destroy).', 'SBOM (SPDX, CycloneDX) is an inventory; VEX says whether a vulnerability affects the product; SCA finds third-party components and licenses; SLSA and provenance protect builds; dependency confusion uses a higher version number.', 'Copyleft (GPL, AGPL) can force source disclosure; permissive (MIT, BSD, Apache 2.0) cannot; Common Criteria EAL1 to EAL7 measures evaluation rigor, not features.']},
    {'heading': 'Exam-day strategy', 'points': ['125 questions in 3 hours is about 1 minute 25 seconds per question; do a first pass, flag the hard ones and return, leaving time to review flagged items. Unanswered questions score zero, so never leave one blank.', 'Scoring is scaled to 1000 with 700 to pass, and an exam can include unscored pretest items, so do not try to count your correct answers during the exam.', 'Questions ask for the BEST, FIRST or MOST appropriate action. The best answer is usually the one that fixes the root cause earliest in the lifecycle, enforces policy by design and involves the accountable owner.', 'Eliminate options that bypass process (quiet exceptions, deleting findings), rely on obscurity, or wait for a penetration test to discover a design problem.', 'Read the scenario for the lifecycle phase: during requirements think classification and abuse cases, during design think threat model and principles, after release think patching, disclosure and end of life.', 'On multiple-response and advanced item types (such as drag-and-drop ordering and matching), read each instruction carefully and use partial knowledge to eliminate wrong options.']},
]
